// SINH TỰ ĐỘNG từ content/qua-chin, content/nghe-pham, content/cai-can, content/canh. Không sửa tệp này.
const ND2_DATA={"qc":{"an_tang":[{"id":"a","ten":"Một người mang đôi giày lẻ","t":"Người đi tìm cha tới chỗ ngươi từng chôn một người chết bên đường. Ông mang chiếc giày lẻ còn lại, nhận ra miếng vá trên chiếc ngươi cất bên mộ. Ông ngồi xuống, xin nghe người mất đã được đặt nằm thế nào.","c":[{"id":"ke","l":"Kể rõ việc chôn cất","t":"Ngươi kể từng việc mình biết. Ông đặt chiếc giày vào chân bia rồi xin ngồi thêm một lúc.","e":{"h":2,"tamma":-2}},{"id":"giu","l":"Để ông xem vật tìm thấy bên mộ","t":"Ngươi giao chiếc giày có miếng vá để ông tự đối. Ông ôm cả hai chiếc trước khi về báo nhà."}]},{"id":"b","ten":"Cỏ mọc ngang tấm bia","t":"Nấm mộ ngươi đắp bên đường đã có cỏ che kín. Một người chăn trâu thường nhổ cỏ quanh bia, chỉ vì từng thấy khách lỡ đường đặt nước ở đó. Hôm nay người ấy hỏi ngươi có biết tên ai nằm dưới mộ.","c":[{"id":"ghi","l":"Ghi điều biết được lên một mảnh gỗ","t":"Ngươi chỉ ghi nơi tìm thấy người mất và ngày an táng. Người chăn cắm mảnh gỗ bên tấm bia.","e":{"h":2}},{"id":"don","l":"Dọn cỏ và chừa lối cho người tới","t":"Ngươi nhổ cỏ quanh chân bia. Người chăn để lại gáo nước cho người tìm mộ sau này."}]},{"id":"c","ten":"Gói hương gửi nhầm người","t":"Một bà tới hỏi ngươi có phải thân nhân người được chôn bên đường. Bà mang hương vì chính bà từng tìm người nhà nhiều năm. Biết ngươi chỉ là người qua đường, bà vẫn muốn gửi lại một nén.","c":[{"id":"thap","l":"Cùng bà thắp hương","t":"Ngươi dẫn bà tới bia. Bà đặt một nén rồi đứng yên nghe gió lùa qua bụi cỏ.","e":{"h":2}},{"id":"giu","l":"Giữ nén hương cho ngày có người nhận","t":"Bà nhờ ngươi giữ nén hương khô. Nếu có gia đình tìm tới, họ sẽ có thứ để thắp ngay."}]}],"ban_dong_doi":[{"id":"a","ten":"Người trở về chống gậy","t":"Người đồng đội ngươi bỏ lại giữa hiểm cảnh đã sống nhờ một đoàn xa lạ cứu. Họ chống gậy tìm tới để hỏi ngươi đã báo người khác quay lại hay chưa. Trên gậy còn buộc mảnh băng của bộ áo cũ.","c":[{"id":"ke","l":"Trả lời trước mặt người từng cứu họ","t":"Ngươi kể mình đã đi đâu sau khi bỏ họ lại. Người đồng đội nhớ từng đoạn và hỏi đến khi rõ.","e":{"h":3}},{"id":"dua","l":"Đề nghị đưa họ tới chỗ bó xương","t":"Họ chỉ gật khi được tự chọn đường. Ngươi đi kế bên, chờ họ tự bước qua từng bậc.","e":{"h":4}}]},{"id":"b","ten":"Hòm đồ chưa có người nhận","t":"Một người gác trạm mang hòm của đồng đội ngươi từng bỏ. Trong hòm còn thư chưa gửi và một chiếc áo để riêng cho người nhà. Họ hỏi ngươi có thể tìm đúng người nhận thay vì để hòm mục ngoài hiên.","c":[{"id":"giao","l":"Đem hòm đến và kể đúng ngày chia tay","t":"Ngươi trao hòm còn niêm. Khi người nhà hỏi, ngươi nói lúc rời đi họ vẫn còn bị thương.","e":{"h":5,"tamma":1}},{"id":"doc","l":"Cho người gác địa chỉ của gia đình","t":"Ngươi chép địa chỉ để họ gửi hòm. Người gác đọc lại từng chữ rồi đặt giấy dưới dây buộc."}]},{"id":"c","ten":"Người đi cùng chọn đứng lại","t":"Một người từng nghe chuyện ngươi bỏ đồng đội nhận ra ngươi khi xếp đoàn. Họ chỉ người đang đau chân rồi nói nếu phải bỏ người giữa đường thì họ thà ở lại. Người coi đoàn đợi ngươi trả lời.","c":[{"id":"cung","l":"Chờ với người bị đau chân","t":"Ngươi chờ cho họ nghỉ và tới chặng sau muộn hơn đoàn. Người ấy tự đi được phần đường còn lại.","e":{"h":6}},{"id":"tach","l":"Để họ tự chọn đoàn khác","t":"Ngươi không giữ họ bằng lời hứa. Họ tìm xe chậm hơn để người bị đau có thể theo cùng."}]}],"bo_roi_gia_dinh":[{"id":"a","ten":"Chìa khóa dưới bát","t":"Nhà mà ngươi bỏ đi vẫn giữ chiếc chìa dưới cái bát úp. Nay một người thân đem chìa tới trao lại, nói họ phải bán nhà để trả tiền cơm trong những tháng ngươi vắng. Người ấy muốn ngươi tới buổi bàn giao.","c":[{"id":"den","l":"Đến giúp dọn đồ và nghe họ nói","t":"Ngươi chuyển từng hòm ra sân. Người thân chỉ chỗ ở mới nhưng xin ngươi đợi được mời rồi mới tới.","e":{"h":6}},{"id":"gop","l":"Gửi phần tiền thuê xe","t":"Ngươi gửi đủ tiền một chuyến xe. Họ nhận để chở đồ và bảo sẽ tự chọn nơi đến.","dk":{"bacTu":120},"e":{"bac":-120}}]},{"id":"b","ten":"Người quen ngoài bến","t":"Một người từng sống cùng nhà thấy ngươi ở bến. Họ đã làm đủ việc qua mùa khó, nay xin ngươi nói rõ có định nhận lại trách nhiệm với đứa trẻ hay chỉ muốn gặp một lần cho yên lòng.","c":[{"id":"nghe","l":"Nghe họ nói trước khi gặp đứa trẻ","t":"Ngươi nghe về những ngày mình vắng. Hai người hẹn chỉ gặp khi đứa trẻ biết trước và muốn gặp.","e":{"h":3}},{"id":"thoi","l":"Để người thân tự nói với đứa trẻ","t":"Ngươi nhường họ quyết định khi nào nên kể. Đứa trẻ đi qua sân, vẫn mải sửa con diều."}]},{"id":"c","ten":"Hũ gạo có hai nắp","t":"Người trong nhà từng phải chia gạo để sống qua những ngày ngươi bỏ đi. Nay họ có một hũ mới, mỗi nắp đánh dấu phần của một người nuôi trẻ. Họ hỏi ngươi có thể góp một bữa, rồi để hai bên tự tính việc sau.","c":[{"id":"gop_com","l":"Góp tiền cho bữa cơm hôm nay","t":"Ngươi gửi tiền mua gạo, không nhận lời thay mặt ai. Người coi bếp đặt thêm một cái bát.","dk":{"bacTu":80},"e":{"bac":-80}},{"id":"tu_choi","l":"Nói rõ mình chưa thể giúp","t":"Họ đậy hũ rồi dùng phần đã dành từ hôm trước. Ngươi nghe tiếng gạo rơi xuống đáy nồi."}]}],"bo_thi":[{"id":"a","ten":"Bát cơm ở chợ sớm","t":"Người từng xin ngươi một bữa cơm nay đã có việc gánh nước ở chợ. Gặp ngươi lúc hàng quán chưa mở, ông kéo ra một cái ghế con và chia nửa phần cơm còn nóng mà chủ sạp vừa trả công cho ông.","c":[{"id":"an_cung","l":"Ngồi ăn chung với ông","t":"Ngươi ngồi xuống. Ông kể bữa cơm ngươi cho đã giúp ông đủ sức đứng chờ việc đến chiều.","e":{"tamma":-2}},{"id":"de_phan","l":"Để ông mang phần cơm về","t":"Ngươi đã có đồ ăn trong túi. Ông gói lại nửa bát, bảo con ông sẽ có cơm nóng trưa nay."}]},{"id":"b","ten":"Đôi dép đan bằng cỏ","t":"Đứa nhỏ từng nhận mấy đồng mua bánh tìm ngươi dưới mái chợ. Nó đang học đan dép và mang theo đôi đầu tiên làm vừa chân người lớn. Một quai còn lệch, nó xin ngươi thử rồi chỉ chỗ bị cấn.","c":[{"id":"thu_dep","l":"Thử dép và chỉ chỗ quai cấn","t":"Ngươi đi vài bước rồi chỉ ngón chân bị cọ. Nó ngồi sửa ngay, bảo mai còn dám mang dép ra bán.","e":{"nang":{"giao":1}}},{"id":"mua_dep","l":"Trả tiền đôi dép đầu tiên","t":"Ngươi mua đôi dép với giá người học việc tự đặt. Nó đếm xu rồi giữ riêng một đồng làm vốn.","dk":{"bacTu":40},"e":{"bac":-40}}]},{"id":"c","ten":"Nồi cháo đổi người coi","t":"Một bà từng nhận tiền của ngươi qua mùa đói đang nấu cháo ở cổng miếu. Bà dành riêng một bát cho khách đến muộn. Khi thấy ngươi, bà chỉ bát ấy, nói hôm nay bà đã có thể san một bữa cho người khác.","c":[{"id":"trong_noi","l":"Trông nồi để bà về ăn cơm","t":"Ngươi coi bếp đến lúc bà quay lại. Một người gánh củi đến muộn vẫn nhận được bát nóng.","e":{"h":2}},{"id":"an_bat","l":"Nhận bát bà để phần","t":"Bà múc thêm chút cháo dưới đáy nồi. Ngươi ăn hết bát rồi giúp bà mang gáo về bên giếng.","e":{"hp":"4%"}}]}],"cuu_nguoi":[{"id":"a","ten":"Bát cháo nóng","t":"Chiều muộn, gió lùa qua mái tranh. Một người đàn bà gầy gò chặn ngươi ở đầu ngõ, tay bưng bát cháo còn bốc khói. Nàng không nói gì lâu lắm, chỉ nhìn. Rồi nàng bảo: năm ấy nếu không có ngươi kéo lên khỏi dòng nước, giờ này nàng đã là nắm xương dưới đáy sông. Đứa con nàng ôm trên lưng ngủ say, má đỏ vì lạnh. Bát cháo loãng, có mấy lát gừng. Ở cái đất này, đó là thứ quý nhất nàng có.","c":[{"id":"an_chao","l":"Ngồi xuống bậc cửa, ăn hết bát cháo","t":"Cháo nhạt, gừng cay nơi đầu lưỡi. Ngươi ăn chậm, nàng đứng nhìn, thỉnh thoảng lau mắt. Khi ngươi trả bát, nàng cúi đầu thật thấp rồi bế con đi vào bóng tối. Trong người ấm lên một chút, không hẳn vì cháo.","e":{"hp":"5%","tamma":-2}},{"id":"gui_lai","l":"Đẩy bát cháo về phía đứa nhỏ","t":"Ngươi bảo để phần cho đứa bé. Nàng lắc đầu, rồi lại gật, rồi khóc không thành tiếng. Đứa nhỏ tỉnh dậy, húp từng ngụm, hai mắt tròn xoe nhìn ngươi như nhìn một bức tượng trong miếu. Đời này có những món nợ trả bằng một bát cháo, và có những món nợ chẳng ai muốn đòi.","e":{"deed":"bo_thi"}},{"id":"hoi_chuyen","l":"Hỏi nàng giờ sống ra sao","t":"Nàng kể chồng mất mùa lũ, nàng đi giặt thuê cho mấy nhà trên trấn, đêm về đan rổ. Không than, chỉ kể. Trước khi đi, nàng dặn ngươi tránh con đường ven rừng phía bắc mấy hôm nay: có người lạ hay lảng vảng ở đó. Một lời dặn nhỏ, nhưng là của người từng suýt chết.","e":{"nang":{"giao":1}}}]},{"id":"b","dk":{"pham":false},"ten":"Người đứng đợi bên đường","t":"Một gã thợ săn đứng chờ bên gốc cây khô, áo da sờn rách, cung đeo sau lưng. Ngươi nhận ra hắn chậm hơn hắn nhận ra ngươi: kẻ năm nào bị thú dữ vồ, được ngươi lôi ra khỏi hang. Giờ hắn biết ngươi đã bước lên đường tu, biết người như ngươi chẳng cần gì của kẻ phàm. Vậy mà hắn vẫn đợi, tay nắm một gói lá nhỏ, nói đó là cây thuốc mọc trên vách đá cao, hắn trèo ba ngày mới hái được.","c":[{"id":"nhan","l":"Nhận gói lá, cảm ơn hắn","t":"Gói lá còn ướt sương. Hắn cười, lộ hàm răng sứt, bảo vậy là hắn yên lòng rồi. Ngươi nhìn bóng hắn khuất sau rặng cây, chợt nghĩ con đường tu dài như thế, mà thứ khiến lòng người nhẹ đi đôi khi chỉ là chuyện của một ngày cũ.","e":{"tamma":-3}},{"id":"tu_choi","l":"Bảo hắn giữ lại mà bán lấy tiền","t":"Hắn cau mày, như bị xúc phạm, rồi thở dài. Cuối cùng hắn nhét gói lá vào túi áo mình, bảo sẽ đem bán đổi gạo cho mẹ già. Trước khi đi hắn ngoái lại, nói một câu ngươi nhớ rất lâu: người được cứu cũng muốn được trả ơn, đừng tước của họ điều đó."}]},{"id":"c","ten":"Cái tên trong sổ chùa","t":"Qua một ngôi chùa nhỏ ven đường, ngươi dừng xin ngụm nước. Lão sư trụ trì lật cuốn sổ công đức cũ, chỉ cho ngươi xem một dòng mực đã phai: có người khắc tên ngươi lên tấm bia nhỏ sau chùa, cầu cho ân nhân bình an. Người khắc là kẻ ngươi từng cứu, nay đã đi xa, không để lại lời nào ngoài dòng chữ ấy. Gió lay chuông gió, tiếng leng keng lạc lõng giữa trưa hè.","c":[{"id":"thap_huong","l":"Thắp một nén hương trước tấm bia","t":"Khói hương bay thẳng rồi tan. Ngươi đứng lâu hơn mình định. Tấm bia nhỏ, chữ khắc vụng, có chỗ sai nét. Nhưng nó vẫn đứng đó qua mấy mùa mưa, như một lời nhắc rằng việc ngươi làm từng có người nhớ.","e":{"tamma":-2,"h":2}},{"id":"cung_chua","l":"Để lại ít tiền cúng chùa","t":"Lão sư nhận, không đếm, bỏ vào ống tre. Lão bảo tiền này sẽ mua dầu thắp đèn cho khách lỡ đường. Ngươi đi, phía sau tiếng mõ đều đều vọng theo, như ai đó vẫn đang đếm những ngày bình an.","dk":{"bacTu":100},"e":{"bac":-100,"deed":"bo_thi"}},{"id":"di_tiep","l":"Gật đầu rồi đi tiếp","t":"Ngươi trả lại bát nước, cảm ơn lão sư rồi bước ra cổng. Có những điều không cần dừng lại lâu mới thấm. Con đường trước mặt vẫn bụi, nhưng bước chân không còn nặng như lúc sáng."}]}],"cuu_nguoi_hy_sinh":[{"id":"a","ten":"Vai trái ngày mưa","t":"Trời vừa đổ mưa, vết thương trên vai ngươi lại nhói. Người từng được ngươi cõng ra khỏi căn nhà sập tìm tới, mang theo một cái đòn gánh đã bào nhẵn. Thấy ngươi định nhấc gùi, anh xin mang giúp đến trạm.","c":[{"id":"nho_ganh","l":"Nhờ anh mang gùi đến trạm","t":"Ngươi trao gùi. Anh đi chậm ở những chỗ trơn, đợi ngươi theo kịp rồi mới bước tiếp.","e":{"h":2,"tamma":-2}},{"id":"hoi_nha","l":"Hỏi căn nhà đã dựng lại chưa","t":"Anh bảo mái còn dột một góc, nhưng đêm nay cả nhà có thể ngủ chung trong gian khô."}]},{"id":"b","ten":"Tiền chuộc chiếc thuyền","t":"Để cứu người dưới nước, ngươi từng bỏ cả chiếc thuyền vào dòng xiết. Hôm nay người sống sót tìm tới bến, trao một túi bạc nhỏ. Nàng đã dành tiền qua mấy mùa vá lưới và chỉ xin ngươi đừng trả ngay.","c":[{"id":"nhan_bac","l":"Nhận số bạc nàng dành dụm","t":"Ngươi nhận túi bạc. Nàng thở phào, ngồi xuống bến như cuối cùng cũng được nghỉ một lát.","e":{"bac":350}},{"id":"gui_lai","l":"Để nàng giữ bạc sửa lưới","t":"Nàng giữ lại tiền, rồi rủ ngươi tới nhà ăn bữa cơm. Hôm ấy nàng không nhắc món nợ nữa."}]},{"id":"c","ten":"Miếng vải lót nẹp","t":"Người từng được ngươi kéo khỏi bánh xe trông thấy ngươi xoa cổ tay đã gãy trong lần cứu họ. Họ mang tới mảnh vải sạch, kể đã hỏi người bó xương cách kê tay khi ngủ để vết cũ bớt đau.","c":[{"id":"thu_nep","l":"Thử kê tay bằng mảnh vải","t":"Ngươi đặt tay lên lớp vải mềm. Cơn nhức dịu bớt, và lần đầu trong buổi ngươi thả lỏng vai.","e":{"hp":"5%"}},{"id":"trao_nguoi","l":"Gửi mảnh vải cho người đang cần","t":"Ngươi chỉ người phu đang giữ cánh tay đau. Hai người đem vải tới hỏi anh có cần dùng không."}]}],"dao_mo":[{"id":"a","ten":"Chiếc bát đặt sai chỗ","t":"Một người mang đồ cúng ra mộ và thấy huyệt từng bị ngươi đào chưa được lấp chắc. Chiếc bát gia đình vẫn dùng đã nghiêng theo đất lún. Họ tìm ngươi vì có người thấy ngươi trở về từ lối ấy.","c":[{"id":"nhan","l":"Nhận việc và phụ đắp lại mộ","t":"Ngươi nói mình đã lấy gì rồi phụ đắp đất. Gia đình giữ lại quyền quyết chỗ đặt bát.","e":{"h":4}},{"id":"gui","l":"Gửi tiền sửa mộ và rời đi","t":"Ngươi trao tiền dưới chân bia. Họ nhận để sửa mộ, nhưng vẫn hỏi đồ cũ đã đi đâu.","dk":{"bacTu":160},"e":{"bac":-160}}]},{"id":"b","ten":"Món đồ cũ trong tủ hiệu","t":"Một người nhận ra chiếc lược gia đình chôn theo người thân trên sạp đồ cũ. Món ấy do ngươi bán sau khi đào mộ. Chủ sạp chưa dám trao, muốn người bán tới xác nhận trước.","c":[{"id":"xac","l":"Xác nhận để họ lấy lược về","t":"Ngươi kể mình lấy nó ở đâu. Chủ sạp trao lược, còn gia đình giữ tờ ghi đường đi của món đồ."},{"id":"chuoc","l":"Bỏ tiền chuộc lược rồi trao lại","t":"Ngươi trả giá chủ sạp đã mua và đứng đợi khi người nhà gói lược vào khăn.","dk":{"bacTu":120},"e":{"bac":-120}}]},{"id":"c","ten":"Người trông mộ mất chỗ ngủ","t":"Sau lần mộ bị đào, người trông mộ phải đem chăn ra ngủ ngoài vườn. Ông tìm ngươi để hỏi có còn ai quay lại. Đêm trước mưa dột, chiếc chiếu phía ngoài vẫn ướt tới mép.","c":[{"id":"noi","l":"Nói rõ chỉ mình ngươi đã tới","t":"Ngươi nói điều mình biết và ghi đường đã đi. Ông mang bản ấy về để hỏi chủ vườn."},{"id":"mua","l":"Mua chiếu khô cho ông qua đêm","t":"Ngươi trả tiền chiếu và giúp chuyển vào mái khô. Ông nhận nhưng vẫn muốn nghe chuyện cái huyệt.","dk":{"bacTu":80},"e":{"bac":-80}}]}],"diet_khau":[{"id":"a","ten":"Bản chép còn ở tay người khác","t":"Người chép thư mang tới bản sao lời khai của kẻ ngươi từng giết để bịt miệng. Họ đã giữ nó qua nhiều chuyến, nay muốn trả cho gia đình người chết. Họ hỏi ngươi có định ngăn họ nữa hay không.","c":[{"id":"de_di","l":"Để họ trao bản chép cho gia đình","t":"Ngươi nhường lối. Tới cửa, người chép gọi đúng tên ngươi để người nhà biết ai đã nghe lời ấy."},{"id":"nhan","l":"Đến cùng họ và nhận việc đã làm","t":"Ngươi đi bên cạnh, nói rõ vì sao người khai không về. Gia đình giữ bản sao và hỏi có ai cùng chịu trách nhiệm.","e":{"h":4,"tamma":2}}]},{"id":"b","ten":"Lời dặn chưa được giao","t":"Một phu trạm đem phong thư chưa giao của người bị ngươi giết để giấu lời khai. Phong thư chỉ dặn người nhà đón con trước mưa. Người phu hỏi tại sao người gửi không còn tới lấy thư trả.","c":[{"id":"giao","l":"Dẫn người phu tới đúng nhà","t":"Ngươi tìm căn nhà được ghi trên phong. Người nhận đọc thư rồi quay sang hỏi ngày người gửi mất.","e":{"h":3}},{"id":"ke","l":"Kể sự thật để phu trạm tự quyết","t":"Ngươi nói vì sao thư nằm lại. Người phu cất phong vào túi trong, bảo sẽ tự giao tận tay."}]},{"id":"c","ten":"Người bỏ buổi làm chứng","t":"Một người hẹn gặp ngươi ngoài chợ rồi đổi ý. Họ từng định làm chứng cùng người đã bị ngươi giết để giấu chuyện. Nay họ cầm phần lời của mình và chỉ xin được đi về mà không có ai bám theo.","c":[{"id":"tranh","l":"Rời chợ trước để họ tự đi","t":"Ngươi đi lối khác. Họ còn đứng bên sạp một lúc lâu rồi mới chịu cất tờ giấy vào áo."},{"id":"boi","l":"Góp tiền cho họ đi nhờ xe","t":"Ngươi trả tiền xe theo lối họ chọn. Người đánh xe chờ họ tự bước lên rồi mới ghìm cương.","dk":{"bacTu":60},"e":{"bac":-60}}]}],"diet_mon_ma":[{"id":"a","ten":"Người giặt áo ở cổng vỡ","t":"Sau trận diệt ma tông, cổng cũ sập một nửa. Người giặt áo thuê tìm ngươi vì muốn nhận chiếc hòm công còn kẹt bên trong. Bà nói trong hòm có tên cả những người chưa từng cầm binh khí.","c":[{"id":"doi","l":"Giúp bà tìm tên những người làm thuê","t":"Ngươi cùng bà chép tên từ sổ còn đọc được. Người đến nhận công có thể chỉ đúng dòng mình.","e":{"h":4}},{"id":"gui","l":"Chuyển lời tới người đang giữ kho cũ","t":"Ngươi đem lời nhắn đến người coi kho. Họ hẹn một buổi để các gia đình tự tới đối."}]},{"id":"b","ten":"Bếp làng hết người canh","t":"Dân dưới sơn môn không còn phải nộp gạo cho người gác cổng cũ. Một bà mang cơm tới cảm ơn, dắt theo cháu từng làm tạp dịch ở đó. Đứa nhỏ chỉ hỏi ngươi có biết người cùng nhóm đã đi đâu.","c":[{"id":"hoi_tin","l":"Dành buổi chiều hỏi tin người còn sống","t":"Ngươi đi hỏi các hộ vừa nhận người về. Đứa nhỏ giữ một địa chỉ để mai tự tìm bạn.","e":{"h":4}},{"id":"nhan_com","l":"Ăn cơm và nghe hai bà cháu kể","t":"Ngươi ngồi nghe đến hết bữa. Bà mừng vì làng được yên, còn đứa nhỏ vẫn dành một bát cho bạn."}]},{"id":"c","ten":"Chìa kho ở đáy áo","t":"Một người sống sót từ sơn môn xin ngươi làm chứng khi trả chìa kho cho dân. Anh từng bị bắt coi cửa và sợ người ta gộp mình với chủ cũ. Mấy hộ đã đứng đợi, tay cầm giấy ghi gạo bị lấy.","c":[{"id":"chung","l":"Đứng chứng cho việc trả kho","t":"Ngươi để anh kể việc mình từng làm trước khi đưa chìa. Các hộ yêu cầu cả sổ gạo được đặt lên bàn.","e":{"h":3}},{"id":"ngoai","l":"Để các hộ tự nhận chìa","t":"Ngươi lui khỏi cửa. Người coi kho đưa chìa cho từng hộ xem rồi đặt nó cạnh tờ kê gạo."}]}],"giet_thu_cuu_sinh":[{"id":"a","ten":"Lối đi dưới vệt móng","t":"Con thú từng vồ người trên đường núi đã chết dưới tay ngươi. Nay nhóm gánh hàng quay lại con đường cũ. Một người chỉ vết móng vẫn còn trên cây và hỏi có nên để trẻ chăn trâu đi lối ấy.","c":[{"id":"xem_loi","l":"Đi một lượt với người gánh hàng","t":"Ngươi cùng họ xem chỗ khuất và chỉ đường dễ nhìn hơn. Họ hẹn đi chung khi qua đoạn vắng.","e":{"h":3,"nang":{"giac":1}}},{"id":"bao_nha","l":"Nhờ họ báo các nhà có trẻ","t":"Ngươi nhờ người đi chợ nhắn về từng nhà. Họ đồng ý dẫn trẻ đi cùng một thời gian."}]},{"id":"b","ten":"Tấm áo người chăn cừu","t":"Người chăn cừu từng thoát khỏi con thú nhờ ngươi mang một tấm áo lót len đến. Chị đã có thể thả đàn trở lại bãi. Một nhà phía dưới cũng mất cừu và đang xin mượn áo qua mùa lạnh.","c":[{"id":"nhan_ao","l":"Nhận áo chị mang tặng","t":"Ngươi thử lớp len còn thơm mùi nắng. Chị nhìn vừa vai mới yên lòng quay về với đàn.","e":{"tamma":-2}},{"id":"gui_ao","l":"Nhờ chị chuyển áo cho nhà đang thiếu","t":"Chị cuộn áo, giữ nguyên dải buộc rồi đem xuống dốc. Ngươi đi cùng đến cửa nhà ấy."}]},{"id":"c","ten":"Chuông đàn trở lại","t":"Tiếng chuông lại vang trên bãi sau lần ngươi hạ con thú ăn gia súc. Dân mang tới phần công đã hứa; trong túi có cả tiền của một hộ vừa mua lại được con dê đầu tiên.","c":[{"id":"nhan_cong","l":"Nhận tiền công dân đã hẹn","t":"Ngươi nhận phần công. Người giữ sổ đọc từng khoản để cả bãi biết việc đã được thanh toán.","e":{"bac":280}},{"id":"tra_ho","l":"Trả phần góp cho hộ mới mua dê","t":"Hộ ấy nhận lại xu rồi xin dành chúng mua cỏ khô, để con dê còn qua mùa lạnh."}]}],"giet_vo_toi":[{"id":"a","ten":"Tên người trở về trên sổ","t":"Một người chép sổ tìm tới với giấy xác nhận người ngươi đã giết chưa hề dính vào vụ án. Gia đình đã chờ qua mấy mùa mới nghe được tên thật. Họ muốn ngươi đứng bên bàn khi dòng kết tội bị xóa.","c":[{"id":"ra_chung","l":"Đứng trước gia đình và kể phần mình","t":"Ngươi kể việc mình đã làm. Người chép ghi tên ngươi vào biên bản, còn gia đình lấy một bản mang về.","e":{"h":4,"tamma":2}},{"id":"roi_di","l":"Rời bàn khi họ đọc tên người mất","t":"Ngươi đi trước khi tờ giấy trao tay. Tới tối, tiếng người chép đọc tên vẫn vẳng trong trí.","e":{"tamma":3}}]},{"id":"b","ten":"Áo của người không về","t":"Một đứa bé ôm chiếc áo lớn đến hỏi người mặc có từng gửi lời gì. Ngươi nhận ra đường vá trên tay áo của người vô tội đã chết. Đứa bé đã mang áo theo nhiều chuyến, mong một người chịu nói thật.","c":[{"id":"noi_that","l":"Nói người ấy đã mất và nhận phần lỗi","t":"Đứa bé không đáp. Nó gấp áo thật chậm rồi xin ngươi chỉ nơi gia đình có thể thắp hương."},{"id":"goi_nguoi","l":"Nhờ một người thân ngồi nghe cùng","t":"Ngươi tìm bà cô của đứa bé. Khi cô tới, nó mới đặt chiếc áo xuống và hỏi lại từ đầu.","e":{"h":3}}]},{"id":"c","ten":"Bữa cơm dành cho người vắng","t":"Chủ quán vẫn để một chỗ trống cho người vô tội mà ngươi đã giết. Người ấy từng trả tiền trước cho một bữa cơm cùng bạn. Chủ quán chưa biết chuyện và hỏi ngươi có thể chuyển lời hẹn hay không.","c":[{"id":"bao_quan","l":"Báo tin cho chủ quán","t":"Ngươi kể đủ để ông tìm đúng nhà. Ông gói phần cơm mang đi, để nguyên chiếc ghế trống."},{"id":"than_nhan","l":"Tìm người bạn được hẹn tới ăn","t":"Ngươi đem tin tới người bạn. Họ đợi ở bàn cũ rồi nhờ ngươi dẫn tới chỗ người mất.","e":{"h":4}}]}],"hanh_hiep":[{"id":"a","ten":"Cửa hàng mở lại","t":"Người bán bánh từng bị ép dọn sạp nay đã trở về chỗ cũ sau khi ngươi đứng ra bênh. Bà đặt lên thớt hai chiếc bánh, một cho ngươi và một cho người gác chợ từng chịu làm chứng.","c":[{"id":"mang_banh","l":"Mang bánh tới người gác chợ","t":"Ngươi tìm đúng người đã làm chứng. Bà bán bánh đợi tới khi cả hai ngồi xuống mới nhóm bếp.","e":{"h":2}},{"id":"nhan_banh","l":"Nhận phần của mình rồi đi","t":"Ngươi nhận bánh còn nóng. Bà cười, bảo giờ cuối ngày có thể về nhà mà không sợ bị chặn."}]},{"id":"b","ten":"Tờ đơn có thêm dấu tay","t":"Một người từng được ngươi bênh trước cửa phủ đem tới tờ đơn đã có dấu của các hộ. Vụ cũ đã được nghe, nhưng một người bán hàng khác vẫn sợ lên tiếng. Họ nhờ ngươi đọc tờ đơn trước khi mang nộp.","c":[{"id":"doc_don","l":"Đọc đơn cho mọi người cùng nghe","t":"Ngươi đọc rõ từng dòng, để người ký sửa điều họ chưa đồng ý. Một người mới xin ghi thêm tên.","e":{"nang":{"giao":1}}},{"id":"giu_rieng","l":"Gặp riêng người còn sợ ký","t":"Ngươi nghe họ nói dưới mái hiên, rồi để họ tự chọn có đưa tên mình vào tờ đơn hay không.","e":{"h":2}}]},{"id":"c","ten":"Cái then được thay","t":"Gia đình từng được ngươi giúp lấy lại tiền công nay đã sửa được cửa. Họ dành một buổi thay then ở nhà người cũng bị quỵt công, rồi mời ngươi mang phần cơm đã nấu ra cho nhóm thợ.","c":[{"id":"cung_lam","l":"Đến đưa cơm và phụ thay then","t":"Ngươi giữ cửa cho họ ráp then, rồi chia cơm. Chủ nhà thử đóng mở mấy lần mới chịu ngồi nghỉ.","e":{"h":4}},{"id":"nhan","l":"Nhận phần cơm rồi chúc họ làm xong","t":"Họ gói phần của ngươi vào lá, dặn khi ghé lại hãy thử cái then từng kẹt lúc trời mưa."}]}],"pha_phong_an":[{"id":"a","ten":"Đèn tắt quanh ngõ","t":"Từ ngày ngươi phá phong ấn, mỗi khi gió từ phế tích thổi lại thì đèn đầu ngõ tắt. Một nhà đã chuyển trẻ sang ngủ nhờ. Người giữ miếu muốn ngươi chỉ chính xác chỗ vết nứt để họ căng dây báo nguy.","c":[{"id":"chi","l":"Dẫn người giữ miếu tới ngoài vết nứt","t":"Ngươi chỉ chỗ mình đã phá rồi giúp treo biển báo ở lối dân hay qua, bên ngoài vùng nguy hiểm.","e":{"h":4}},{"id":"bao","l":"Báo việc đã xảy ra cho các hộ","t":"Ngươi kể đúng việc mình làm và lúc đèn bắt đầu tắt. Các hộ tự chia phiên đưa trẻ đi."}]},{"id":"b","ten":"Người còn thức sau khuya","t":"Một người gác đường nhận ra ngươi từng mở phong ấn. Sau lần ấy có thứ theo tiếng chân về tới làng, khiến họ phải bỏ việc đêm. Hôm nay họ hỏi có thể nhờ ngươi đứng cùng họ tới sáng không.","c":[{"id":"truc","l":"Ở cùng người gác tới khi trời sáng","t":"Ngươi mang đèn ra ngồi cạnh. Khi nghe tiếng lạ, hai người gọi người trong nhà thay vì đi theo.","e":{"h":8}},{"id":"gop","l":"Góp tiền thay đèn quanh lối","t":"Ngươi giao tiền dầu cho người gác. Họ giữ đủ cho đêm nay và chia phần thừa cho nhà cuối dốc.","dk":{"bacTu":90},"e":{"bac":-90}}]},{"id":"c","ten":"Tờ bùa bị trả về","t":"Người ở chân núi trả ngươi tờ bùa nhặt được gần chỗ phong ấn vỡ. Họ không biết đọc nhưng nhớ sau ngày ngươi tới, gia súc không còn dám đến giếng. Họ muốn đem giấy tới thợ trận để hỏi.","c":[{"id":"dua","l":"Cùng họ đem giấy đi hỏi thợ trận","t":"Ngươi đi với họ và nhận việc đã phá ấn. Thợ trận nghe xong đánh dấu vùng cần tránh.","e":{"h":5}},{"id":"de","l":"Để họ giữ giấy và ghi đường tìm thợ","t":"Ngươi chép chỗ tìm người hiểu ấn. Họ đi trước khi trời tối, kẹp giấy trong tấm vải."}]}],"phong_sinh":[{"id":"a","ten":"Chiếc vòng chân đã rơi","t":"Con chim ngươi từng thả khỏi lồng lại đậu trên mái, chân còn vết cọ. Nó kéo từng cọng rơm lên làm tổ. Người nuôi chim cũ đứng ngoài cổng, hỏi ngươi có muốn giúp bắt lại vì nó vẫn nhớ chỗ ăn.","c":[{"id":"giu_to","l":"Xin chừa mái cho chim làm tổ","t":"Ngươi xin người trong nhà hoãn sửa góc mái. Người nuôi chim nhìn một lúc rồi cuộn lưới đi.","e":{"tamma":-2}},{"id":"hoi_gia","l":"Hỏi vì sao người nuôi muốn bắt lại","t":"Người ấy nói chim đã từng mang tiền về cho nhà. Ngươi nghe hết, rồi chỉ chỗ còn chiếc vòng rơi."}]},{"id":"b","ten":"Cá về cửa lạch","t":"Bầy cá từng mắc trong đăng đã bơi xuống lạch nhờ ngươi mở lối. Qua mùa nước, lũ nhỏ đem giỏ tới hỏi có nên đặt đăng ngay nơi cá con quay về. Một đứa chỉ những vệt bạc dưới chân cầu.","c":[{"id":"doi_cho","l":"Chỉ chỗ đặt đăng xa đàn cá con","t":"Ngươi dắt chúng xuống đoạn nước sâu hơn. Chúng vẫn có cá mang về mà lối vào bãi giống còn mở.","e":{"h":2}},{"id":"bao_nguoi","l":"Gọi người đánh cá tới bàn","t":"Ngươi mời những nhà đặt đăng cùng xem đàn cá nhỏ. Họ hẹn sáng mai bàn phần được giữ lại."}]},{"id":"c","ten":"Lồng rỗng phơi ngoài vách","t":"Người từng bán cho ngươi con thú để thả đem chiếc lồng rỗng ra phơi. Sau lần ấy, nàng bỏ việc giữ thú và tập đan rổ. Nàng nhờ ngươi xem chiếc rổ đầu có chịu nổi một gánh rau không.","c":[{"id":"thu_ro","l":"Giúp nàng thử đựng một gánh rau","t":"Ngươi đặt rau vào rổ và thấy đáy còn võng. Nàng buộc lại đáy, rồi mang chiếc đã sửa ra chợ.","e":{"nang":{"khao":1}}},{"id":"mua_ro","l":"Mua rổ để nàng có tiền lấy tre","t":"Ngươi trả giá nàng đã đặt. Nàng ghi món thu đầu vào bảng gỗ từng treo bên chiếc lồng.","dk":{"bacTu":60},"e":{"bac":-60}}]}],"tha_ke_ac":[{"id":"a","ten":"Dây buộc thay chuôi đao","t":"Kẻ từng quỳ xin tha nay đứng trong hàng người vá mái sau bão. Ngươi nhận ra vết mẻ trên chiếc đao hắn đã nộp, giờ dùng để chẻ lạt. Một chủ nhà từng bị hắn lấy của vẫn đứng ngoài nhìn.","c":[{"id":"hoi_chu","l":"Hỏi chủ nhà có muốn nói chuyện","t":"Ngươi đợi chủ nhà đồng ý mới dẫn hắn tới. Người ấy chỉ đòi trả chiếc rương đã mất.","e":{"nang":{"giao":1}}},{"id":"thoi","l":"Để họ tự quyết việc gặp nhau","t":"Ngươi rời sân. Hắn tiếp tục vá mái, còn chủ nhà giữ khoảng cách và không bị ai giục tha thứ."}]},{"id":"b","ten":"Lời cảnh báo trước phiên chợ","t":"Người ngươi từng tha đợi ở quán nước. Hắn báo đám cũ sắp tới đòi tiền những sạp từng nộp cho chúng. Hắn muốn nói trước với dân nhưng sợ họ nhìn thấy mặt mình rồi đóng cửa.","c":[{"id":"bao_chung","l":"Đi cùng hắn để báo các sạp","t":"Ngươi đi cùng. Dân đem tiền hàng về nhà trước tối, còn hắn phải nghe một người nhắc lại khoản đã cướp.","e":{"h":3}},{"id":"de_kin","l":"Chuyển lời mà giấu tên người báo","t":"Ngươi chỉ nói điều mình nghe được. Họ chuẩn bị cất hàng, nhưng vẫn chưa biết ai trong nhóm cũ đã đổi ý."}]},{"id":"c","ten":"Chiếc bọc đựng tiền trả","t":"Ngươi gặp kẻ từng đầu hàng bên một chiếc bọc khâu lại nhiều lần. Hắn bán công ở bến, dành được ít bạc trả người bị hại. Hắn hỏi có thể mượn ngươi làm chứng cho số tiền giao hôm nay không.","c":[{"id":"chung","l":"Đứng chứng lúc hắn trả tiền","t":"Ngươi đếm cùng hai bên rồi để họ tự ký. Người nhận ghi phần đã trả và phần còn thiếu.","e":{"h":2}},{"id":"gui","l":"Bảo hắn tìm người nhận rồi tự giao","t":"Hắn cất bọc vào áo. Khi gặp người ấy, hắn tự đọc món nợ, không mượn tên ngươi để xin bỏ qua."}]}],"tham_o":[{"id":"a","ten":"Mái sập vì tiền bị rút","t":"Một phần tiền tu sửa mái chợ từng vào tay ngươi. Mưa vừa làm mái sập, một người bán nước phải nghỉ vì bị thương. Người coi chợ đem sổ chi tới hỏi vì sao số ngói mua ít hơn số có trên giấy.","c":[{"id":"tra","l":"Trả một phần tiền cho người bị thương","t":"Ngươi giao tiền trước người coi chợ. Người bán nước ghi đã nhận và xin giữ nguyên tờ trình.","dk":{"bacTu":400},"e":{"bac":-400}},{"id":"ke","l":"Chỉ dòng tiền bị lấy trước buổi xét","t":"Ngươi mở sổ và kể ai đã nhận phần tiền. Người coi chợ chép nguyên lời rồi đóng dấu.","e":{"h":4,"tamma":2}}]},{"id":"b","ten":"Dấu chi trong sổ áo","t":"Người từng chép thay ngươi một khoản chi mang bản nháp tới. Họ sắp bị bắt nhận phần thiếu do khoản ngươi đã lấy. Họ chỉ xin ngươi xác nhận ai đã bảo chép dòng cuối.","c":[{"id":"nhan","l":"Nhận mình đã ra lệnh ghi sai","t":"Ngươi nói trước người xét sổ. Người chép giữ biên bản để tự đối khi bị gọi lần sau.","e":{"h":3}},{"id":"sao","l":"Cho họ sao giấy để tự trình","t":"Ngươi để họ chép dấu vào bản nháp. Họ cất giấy trong áo và tự tới bàn xét."}]},{"id":"c","ten":"Hàng gạch còn thiếu","t":"Một người lấy gạch dựng lại bờ giếng hỏi ngươi vì sao phần ngân quỹ họ từng xin lại ghi đã dùng hết. Món ấy từng bị ngươi lấy. Dưới giếng, một đứa nhỏ đang đợi người lớn kéo nước lên.","c":[{"id":"gop","l":"Bỏ tiền mua phần gạch thiếu","t":"Ngươi trả tiền cho số gạch còn thiếu. Người coi giếng ghi rõ khoản này đến từ ngươi.","dk":{"bacTu":280},"e":{"bac":-280}},{"id":"ghi","l":"Cùng họ kê lại kinh phí thật","t":"Ngươi ghi số gạch thật và phần không có biên nhận để họ còn trình lên khi cần.","e":{"h":2}}]}],"trom_ngheo":[{"id":"a","ten":"Chiếc bị rỗng bên cầu","t":"Người bán rau từng mất túi tiền vì ngươi vẫn đeo chiếc bị rách quai. Bà phải mua chịu giống sau hôm đó và vừa trả được phần lãi. Gặp ngươi bên cầu, bà nhờ đọc hộ tờ ghi nợ còn lại.","c":[{"id":"tra","l":"Trả lại một phần số tiền đã lấy","t":"Ngươi đặt xu trước mặt bà và nói vì sao. Bà tự đếm rồi cất riêng vào túi đựng tiền giống.","dk":{"bacTu":140},"e":{"bac":-140}},{"id":"doc","l":"Đọc nguyên tờ nợ cho bà nghe","t":"Ngươi đọc cả tiền gốc lẫn phần lãi. Bà chép dấu của chủ nợ để còn mang đi hỏi lại."}]},{"id":"b","ten":"Bữa thuốc bị lỡ","t":"Một người lao động nhận ra ngươi gần nơi mình mất tiền. Họ kể số tiền ấy để mua thuốc cho mẹ và bà đã phải chờ thêm mấy hôm. Hôm nay họ chỉ mang đơn cũ tới để hỏi nhà thuốc còn bán chịu không.","c":[{"id":"doi","l":"Trả giúp tiền thang thuốc còn thiếu","t":"Ngươi đặt tiền vào tay người cầm đơn, để họ tự mua. Họ nhận nhưng không nói món cũ đã qua.","dk":{"bacTu":100},"e":{"bac":-100}},{"id":"dung","l":"Dừng lại nghe họ kể hết","t":"Ngươi nghe tới hết chuyện bữa thuốc. Họ gập đơn rồi bước vào hiệu, không nhờ ngươi nói thay."}]},{"id":"c","ten":"Chiếc giỏ để quên","t":"Đứa bé giữ sạp đưa lại chiếc giỏ ngươi bỏ quên. Nhà nó từng phải bán nồi vì mất món tiền ngươi lấy. Nó không nhận ra ngươi và chỉ dặn giữ giỏ chặt khi qua chỗ đông.","c":[{"id":"gui","l":"Hỏi có thể giúp mua lại nồi không","t":"Ngươi góp phần mình có, để nó tự mang về hỏi người nhà. Nó buộc tiền ở đáy giỏ.","dk":{"bacTu":120},"e":{"bac":-120}},{"id":"nhan","l":"Nhận giỏ và cảm ơn đứa bé","t":"Ngươi nhận lại đủ đồ. Lúc quay lưng, ngươi nghe nó hỏi chủ sạp có thể ứng tiền công hay chưa."}]}]},"nghe":{"binh":{"len":["Ngươi được giao coi một toán nhỏ. Tới giờ điểm danh, người lính trẻ xin nói ai còn mắc ở chỗ phát lương.","Người giữ cửa giao thêm lính cho ngươi. Trước lần đổi gác, ngươi để từng người nhận lại đủ áo qua đêm lạnh.","Ngươi nhận quyền coi cả đội và phải đọc lệnh rút cho những người ở cuối hàng. Họ hỏi chỗ nào còn lương.","Báo từ nhiều toán về cùng một lúc. Ngươi phải nghe cả người đứng cuối kho, vì họ biết bao nào chưa từng mở.","Khi nhận cờ tướng quân, ngươi được hỏi sẽ làm gì với những nhà lính phải chuyển khỏi phía dưới cửa ải.","Các đội chờ ngươi định thứ tự tiếp tế. Trước bàn lệnh, một lính già đem danh sách những người còn chưa về."],"ket":[{"id":"A","ten":"Đủ tên qua cổng","t":"Ngày ngươi mất, đội trực đọc danh sách cả người đã về và người còn thiếu. Gia đình lính có thể tra phần lương trước lúc đưa tang. Một người từng được gọi về đúng giờ mang đến chiếc áo mặc trong đêm rút quân.","dk":{"bacNgheTu":5,"nghiep":"thien"}},{"id":"B","ten":"Kho còn lệnh cấm mở","t":"Ngươi mất khi kho vẫn còn bao thóc chờ lệnh. Một số thân nhân cầm phiếu tới đòi lương, kể cả nhà có người từng bị giữ gác quá hạn. Người nhận cờ phải giữ các phiếu ấy cùng lệnh ngươi để lại.","dk":{"bacNgheTu":5,"nghiep":"ac"}},{"id":"C","ten":"Phiên gác sau cùng","t":"Đội thay ca đến đưa tang ngươi rồi quay lại gác đúng giờ. Một cựu binh đem đèn treo ở chỗ dân hay qua. Họ vẫn nhớ ngươi từng cho nghỉ để người bị thương kịp về với gia đình.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Áo vải gấp tư","t":"Ngươi chết với chiếc áo lính đã vá nhiều lượt. Người cùng toán gấp áo, trả tiền công còn thiếu cho gia đình rồi ăn bữa cơm sau tang. Họ nhớ ngươi vì luôn chừa nước cho người trực sau."}]},"chep":{"len":["Thầy cho ngươi ghi tên vào sổ đồng sinh. Trang đầu ngươi tự chép dành cho một đứa bé chưa có tiền mua giấy.","Sau kỳ khảo, người trong làng gọi ngươi là tú tài. Họ đem tờ thuế đến nhờ ngươi đọc từng dòng bằng tiếng thường.","Tờ báo đỗ về đến cổng trước ngươi. Một người từng cho mượn đèn tới hỏi có thể xem lại quyển ngươi đã viết không.","Ngươi nhận tên tiến sĩ và một chỗ dạy ở kinh. Chuyến về quê, ngươi mang theo giấy để học trò được tự chép.","Học trò từ xa đến hỏi cách đọc sử. Ngươi đặt hai bản trái nhau lên bàn, giữ cả lời người mà sử quan đã bỏ."],"ket":[{"id":"A","ten":"Bản sách nằm ngoài thư khố","t":"Khi ngươi mất, học trò tìm lại đủ hai bản của một vụ án từng bị chép lệch. Họ giữ một bản ở làng, một bản ở nơi dạy học. Người đọc về sau có thể thấy lời của những gia đình từng bị gạch tên.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Quyển chép còn nét tẩy","t":"Người giữ thư phòng niêm tủ trước giờ đưa tang. Học trò tìm thấy tờ có nét ngươi sửa theo lệnh, cạnh một tờ hứa trả công. Họ giữ cả hai để người sau biết trang nào từng được trả giá.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Lớp bên ngọn đèn cũ","t":"Sau khi chôn ngươi, mấy học trò góp dầu để lớp còn mở vào tối. Họ đặt tờ đối nét của ngươi ngoài cửa. Một người đi nộp thuế ghé vào xin con đọc giúp tờ quan vừa gửi.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Giấy tập chữ phơi lại","t":"Gia đình đem tập giấy của ngươi hong sau ngày mưa đưa tang. Một đứa trẻ đọc được tên mình trong trang ngươi từng chép hộ. Nó xin giữ trang ấy, rồi lại kê giấy lên bàn học."}]},"chuong":{"len":["Một nhóm học trò xin ở lại sau buổi tập. Họ muốn dựng tiểu phái và hỏi ngươi sẽ đặt lệ vào học như thế nào.","Người từ các thôn tới xin gửi con học võ. Ngươi phải sắp lịch cho những em còn phải về nhà trước chiều.","Nhiều võ quán mang thư tới hỏi học trò có thể tập chung không. Ngươi đặt một bàn để nghe cả lời phía ít người.","Các võ phái khác xin ngươi đứng ra phân xử một cuộc tranh sân. Học trò hỏi có được góp lời nếu không đồng ý.","Người khắp nơi gọi ngươi là bậc đứng đầu giới võ. Sáng ấy, một người mới vẫn phải đứng ngoài vì chưa có ai nhận."],"ket":[{"id":"A","ten":"Đèn sân truyền qua tay","t":"Sau khi ngươi mất, môn đồ để người học tự chọn thầy và giữ quyền rời sân. Họ cử một người mở cửa cho trẻ không đủ phí. Đứa nhỏ từng đứng ngoài quay lại đặt bó củi đầu tiên dưới đèn.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Danh thiếp còn kèm khoản nợ","t":"Các chi nhánh gửi lễ tới đám tang, rồi hỏi phần phí phải nộp từ nay. Một môn đồ cầm danh thiếp cũ xin được thôi mà không mất việc. Người kế vị phải mở sổ những lời hứa ngươi đã buộc họ ký.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Sân cũ còn tiếng chân","t":"Sau lễ tang, vài học trò tổ chức lại buổi tập trên nền cũ. Họ để nguyên hàng ghế thấp nơi ngươi từng ngồi chỉ thế đứng. Người đi ngang còn nghe tiếng họ đếm nhịp qua cửa.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Tấm biển tự tay treo","t":"Võ quán nhỏ khép cửa khi ngươi qua đời. Người từng đến tập thỉnh thoảng ghé lau tấm biển đã bạc màu. Một người đem cất nó sau trận mưa lớn để con cháu còn biết đây từng là nơi học võ."}]},"do":{"len":["Chủ đò giao mái chèo cho ngươi tự đưa khách sang. Người lên đầu tiên hỏi có thể đặt gánh xuống đâu cho khỏi ướt.","Ngươi có đò của mình và phải lo cả phần vá. Người từng chở cùng hỏi có thể nhận một lượt chèo khi ngươi nghỉ không.","Dân bến đưa bảng lượt cho ngươi giữ. Một người về muộn muốn biết còn chuyến cuối hay phải đợi qua đêm.","Các lái đò hỏi ai được chở hàng qua lúc nước lên. Ngươi phải ghi riêng chỗ cho người đi khám và người bán hàng.","Người từ nhiều bến đem sổ tới xin ngươi định phí. Họ để chỗ trống cho nhà còn chưa qua được sau mùa nước."],"ket":[{"id":"A","ten":"Đèn cho chuyến muộn","t":"Sau khi ngươi mất, người giữ bến vẫn dặn để một thuyền chờ khách về muộn. Họ giữ mái chỗ ngồi cho người không qua được ngay. Một nhà sống sót qua lũ đem dầu tới thắp đèn hôm đưa tang.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Bến có người đứng thu","t":"Người thừa kế nhận cọc bến và tờ ghi mức phí. Sau lễ tang, một người từng bị giữ hàng vì thiếu tiền đến đòi lại biên nhận. Sổ vẫn có tên họ dưới dấu ngươi, cùng giá tăng hôm nước lớn.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Mái chèo dưới sạp","t":"Chiếc đò vào tay người từng chèo thay khi ngươi ốm. Họ đặt mái chèo dự phòng ngay dưới sạp và dùng lối ngươi từng chỉ lúc nước xoáy. Khách qua bến vẫn hỏi thăm nhà ngươi sau ngày tang.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Cọc buộc trước bình minh","t":"Ngươi sống bằng công từng lượt đò. Khi ngươi qua đời, người lên đò đầu tiên hôm ấy tự buộc lại dây cho chủ bến. Họ nhớ ngươi hay chờ một lát để người gánh nặng kịp xuống."}]},"hat":{"len":["Bầu gánh giao ngươi một vai có lời. Người nhắc tuồng ngồi sát màn để ngươi còn nghe khẽ khi quên câu.","Khách đã tới để xem vai chính của ngươi. Sau buổi, người kéo màn hỏi bao giờ được tập thay một đoạn.","Ngươi nhận sổ công và lịch diễn. Cùng ngày có người xin nghỉ vì đau chân và một chủ sân muốn mua thêm buổi.","Tiếng hát của ngươi được mời sang phủ khác. Một học trò gấp áo diễn giúp và hỏi có được học đoạn khó nhất không.","Người ở xa đem bản tuồng đến đối lời. Ngươi giữ cả câu đã từng bị cấm để người sau biết nó bị bỏ ở đâu."],"ket":[{"id":"A","ten":"Đèn sân có người nối","t":"Khi ngươi mất, học trò treo chiếc đèn cũ rồi chia công như đã học. Họ diễn một vở từng có người xin giữ nguyên lời ở chợ. Sau buổi, người kéo màn được gọi ra trước sân để mọi người cảm ơn.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Giấy diễn để trong hòm","t":"Đoàn còn tiền sau khi chôn ngươi, nhưng mọi lời phải qua bên giữ ấn. Một người từng xin hát chuyện nhà mình giữ trang đã bị gạch. Người kế đoàn cất trang ấy cạnh giấy cho diễn riêng.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Vai cũ còn người nhắc","t":"Sau tang lễ, người từng nhắc tuồng mở tập giấy ngươi gập ở đoạn khó. Họ dạy vai ấy cho một người đứng sân mới, kể vì sao ngươi thường dừng lại để nghe khán giả còn thở hay không.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Dây màn buộc lại","t":"Ngươi qua đời ở nơi đoàn ghé qua. Người kéo màn dùng dây đã vá để buộc hòm đồ, rồi đặt phần công còn lại vào tay người nhà. Trong một buổi diễn sau, họ nhắc đúng câu ngươi từng sợ quên."}]},"khat_cai":{"len":["Người coi chợ chừa cho ngươi một chỗ ngồi quen. Một đứa mới tới hỏi khi nào được ngồi đó mà không bị xua.","Những người ngủ dưới sạp nhờ ngươi chia phần cơm. Có người xin để riêng một bát cho người đang đi đưa tin.","Trưởng lão trong thành mời ngươi giữ việc ở vài ngõ. Ba người đem giấy tới hỏi tiền chỗ ngủ đã đi về đâu.","Ngươi nhận phần coi một nhánh Cái bang. Người trú dưới mái mới muốn biết được đi sang nơi khác lúc nào.","Các nhánh đem sổ tới xin ngươi chia phần qua mùa. Ngoài cửa có người mới tới mà chưa ai biết tên."],"ket":[{"id":"A","ten":"Nồi cơm có phần người mới","t":"Sau khi ngươi mất, người giữ chợ vẫn múc một bát để ngoài hàng cho ai đến muộn. Đứa từng được nhận ngủ dưới mái trả tiền công đầu để mua gạo. Họ kể về ngươi bằng cái tên ngươi từng tự chọn.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Tên dưới sổ thu phần","t":"Bang giữ được các ngõ sau lễ tang, nhưng người làm tin phải nộp phần như cũ. Một đứa từng bị cắt cơm mang tờ phạt tới và xin được ghi năm ấy ai đã ký. Người kế bang nhận tờ giấy trước mặt cả nhóm.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Dấu biết chỗ trú","t":"Người từng ngủ chung sạp thay nhau đưa ngươi đi chôn. Họ giữ cách buộc dây ở mái khô để người đi đêm biết có chỗ nằm. Một người mới hỏi ai đã chỉ dấu ấy và nghe câu chuyện bên nồi cơm.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Chiếc bát rửa lần cuối","t":"Khi ngươi không còn, bạn ngồi chợ rửa chiếc bát cũ rồi để cạnh giỏ tang. Họ trả chỗ ngồi cho đứa đến sau. Mỗi chiều, người bán nước vẫn nhớ ngươi từng đỡ họ kéo thêm một gàu."}]},"mo":{"len":["Người coi cửa phát cho ngươi thẻ xuống hầm. Ngươi đã có thể cầm cuốc trong ca thay vì chỉ gùi quặng ra ngoài.","Thợ mới đợi ngươi chỉ chỗ đổi tay trước khi vào ca. Khi hết lượt, họ đưa ngươi đếm lại đủ thẻ rồi mới về.","Chìa cửa hầm được giao cho ngươi. Một thợ xin đổi ca để chăm người bệnh và chờ ngươi ghi rõ vào bảng.","Người luyện quặng tới chờ lệnh mở lò. Ngươi xem phiếu cân cùng thợ, rồi để họ tự đối phần công trước khi đốt.","Khi nhận cả mỏ, ngươi phải quyết việc một cửa hầm đã yếu. Trước cửa có người hỏi nếu đóng thì họ còn việc ở đâu."],"ket":[{"id":"A","ten":"Tên cạnh giờ lên hầm","t":"Sau khi ngươi mất, người coi ca vẫn đọc tên từng thợ lúc lên. Bảng cũ có một dòng về cửa hầm phải đóng nếu thiếu gió. Gia đình một người từng được đưa ra kịp giữ bản chép ấy trong nhà.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Quặng chất sau cửa khóa","t":"Người thừa kế nhận hòm tiền đầy cùng một sổ công chưa trả. Đến ngày chôn ngươi, mấy thợ cầm thẻ quá hạn đứng chờ ở cửa thay vì theo đám. Họ xin người coi mỏ ghi lại ngày đáng lẽ đã được rời.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Chỗ ngồi của thợ cả","t":"Thợ cùng ca đem cái ghế thấp của ngươi lên cửa hầm ngày đưa tang. Họ để nó ở nơi đếm người, dặn thợ mới khi lên phải tự gọi tên mình. Người từng được ngươi đổi ca trở về giúp nhà lo cơm.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Chiếc gùi đặt xuống","t":"Ngươi không để lại phần mỏ nào, chỉ có chiếc gùi mòn vai. Người cùng đường đưa nó cho con ngươi, trong đáy còn một mẩu than dùng ghi công. Họ ngồi bên hiên kể về những chuyến đưa quặng cuối mùa mưa."}]},"ngu":{"ket":[{"id":"A","ten":"Đèn chờ thuyền về","t":"Đêm ngươi mất, cả bến thắp đèn trên những chiếc thuyền từng được ngươi cho đi chung mùa nước xấu. Người giữ lượt kéo lưới tiếp quản kho dây và để mọi nhà mượn khi cần. Con ngươi giữ chiếc phao cũ treo ngoài mái để người về muộn biết bến vẫn sáng.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Sổ cá dưới đáy hòm","t":"Ngươi để lại đội thuyền và một cuốn sổ ghi nhà nào còn nợ lưới. Khi ngươi chết, người kế sổ gọi những hộ ấy tới trước khi đưa tang. Một ngư phủ giữ bản nợ vì muốn sau này con mình biết tại sao nhà từng phải bán thuyền.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Chiếc mái chèo truyền tay","t":"Chiếc thuyền nhỏ vào tay người từng phụ ngươi vá lưới. Sau khi chôn ngươi, họ giữ mái chèo cũ làm mái dự phòng. Lần đầu gặp gió ngược, họ nhớ lời ngươi dặn chờ nước đổi rồi mới rời bến.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Một mẻ cá cuối ngày","t":"Khi ngươi mất, chủ thuyền trả nốt tiền vá lưới cho gia đình. Người từng ngồi vá bên ngươi chừa một chỗ trên sàn gỗ đến hết mùa nước, rồi dạy đứa trẻ ở bến cách luồn kim qua mắt lưới."}]},"nong":{"ket":[{"id":"A","ten":"Người giữ kho thóc của làng","dk":{"bacNgheTu":4,"nghiep":"thien"},"t":"Năm đói lớn, ngươi mở kho phát thóc, không ghi nợ ai. Ruộng nhà ngươi sau này chia nhỏ cho những người từng cấy thuê, mỗi nhà một mảnh. Khi ngươi nằm xuống, người trong thôn khiêng quan tài đi chậm qua cánh đồng, dừng lại ở từng bờ ruộng như để ngươi xem lần cuối. Kho thóc cũ thành nơi cả làng gửi giống, gọi là kho chung, cửa không bao giờ khoá."},{"id":"B","ten":"Văn tự trong rương gỗ","dk":{"bacNgheTu":4},"t":"Ngươi chết giữa những rương văn tự. Con cháu chia nhau ruộng đất trước khi tang lễ xong, cãi nhau to tới mức quan huyện phải sai người tới. Những kẻ cấy thuê đứng ngoài cổng nhìn vào, không ai khóc. Mấy năm sau, ruộng nhà ngươi về tay một nhà giàu khác, và người ta lại cấy, lại nộp tô, như chưa từng có ngươi."},{"id":"C","ten":"Mảnh ruộng bên bờ mương","dk":{"bacNgheTu":2},"t":"Mảnh ruộng nhỏ cạnh bờ mương vẫn ở đó, giờ con ngươi cấy. Đời ngươi không giàu, không nghèo, vài lần mất mùa, vài lần được mùa, đủ cho nhà khỏi đói. Người ta chôn ngươi ở góc ruộng, dưới gốc gạo già. Mùa xuân hoa gạo đỏ rơi đầy mặt nước, đứa cháu nhỏ hay ra nhặt về chơi."},{"id":"D","ten":"Kẻ làm thuê không tên","t":"Ngươi cấy ruộng người khác cả đời, lưng còng xuống theo từng mùa gặt. Không có mảnh đất nào mang tên ngươi. Khi ngươi chết, chủ ruộng cho mấy đấu thóc làm ma, coi như trả công những năm cũ. Nhưng mấy đứa trẻ chăn trâu trong thôn vẫn nhớ người đàn ông hay chỉ chúng cách bắt cá trong ruộng ngập, và đôi khi, lúc trời chiều, chúng còn hát lại câu hò ngươi dạy."}]},"quan":{"len":["Tờ bổ nhiệm đưa ngươi từ bàn chép sang bàn xét việc huyện. Người nộp đơn đầu tiên muốn biết có được giữ bản sao không.","Tại huyện nha, ngươi nhận ấn xử việc. Trước cửa có một hộ mang biên nhận thuế tới, chờ ngươi nghe họ đọc.","Các huyện gửi án lên phủ để ngươi xét lại. Một người từng bị xử vắng mặt xin được đứng trước bàn nói phần mình.","Ngươi coi việc cả châu. Trước kỳ thu, người dưới kho đem tới những sổ có số thóc không khớp nhau.","Khi nhận chức thượng thư, ngươi phải đọc cả phần lương đã chuyển và phần dân còn phải nộp ngay trước triều.","Ấn tể tướng đặt cạnh tờ bãi chức. Người đem đơn được đứng lâu đủ để giải thích vì sao họ đã đi qua nhiều cửa."],"ket":[{"id":"A","ten":"Cửa nhận đơn không đóng","t":"Sau khi ngươi mất, người giữ nha môn vẫn cho dân lấy bản sao trước khi ra về. Một người được sửa sổ thuế mang tới giấy cũ để đặt cạnh hương. Họ bảo đã thôi phải nộp lại khoản nhà từng đóng.","dk":{"bacNgheTu":5,"nghiep":"thien"}},{"id":"B","ten":"Ấn đặt trên chồng nợ","t":"Ngươi chết, ấn được trả nhưng các tờ thu quá mức vẫn còn. Vài nhà đưa tang xong quay lại đòi xét phần của họ. Người kế chức mở sổ và thấy nhiều dòng có chính chữ ngươi bên cạnh chỗ bị thêm.","dk":{"bacNgheTu":5,"nghiep":"ac"}},{"id":"C","ten":"Tờ án có ngày trả lời","t":"Người giữ việc huyện tìm thấy trong hòm ngươi những đơn đã ghi ngày phải đáp. Sau tang lễ họ tiếp tục gọi từng nhà. Có người tới nhận lời xét lần đầu và để lại một tờ cảm tạ không đề tên.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Tên người chép ở cuối trang","t":"Ngươi chết trước khi được cầm ấn lớn. Một người từng ngồi chờ đọc đơn mang giấy đến đặt bên mộ. Họ vẫn nhận ra nét ngươi ở cuối trang, dưới lời xác nhận số tiền họ đã nộp."}]},"ren":{"len":["Thợ cả để ngươi tự gắp phôi khỏi lửa. Lần này người kéo bễ đứng cạnh ngươi, chờ nghe lúc cần dừng.","Người mang cuốc tới hỏi ngươi chọn sắt thay vì chờ chủ lò. Món đầu sửa xong đã được đem thẳng ra ruộng.","Chùm chìa của lò về tay ngươi. Thợ hỏi hôm nào lĩnh công, còn khách đã đặt trước lưỡi cày cho mùa tới.","Người mua từ xa tới xem dấu búa nhà ngươi. Ngươi để họ thử một lưỡi trước khi nhận cả lô đem đi.","Những lò khác gửi người tới học. Ngươi trải các mẫu đã hỏng lên bàn, chỉ cả chỗ sắt nứt và chỗ thợ đánh quá tay."],"ket":[{"id":"A","ten":"Búa còn bên đe","t":"Sau khi ngươi mất, người học việc dùng búa của ngươi sửa miễn công lưỡi cuốc đầu mùa cho một nhà cũ. Họ giữ lệ cho khách thử ngay trước bệ. Từ xa, người ta còn mang đồ hỏng tới vì tin sẽ được nói rõ có sửa được không.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Dấu lò trên bao kiếm","t":"Người bảo trợ gửi xe tới lấy lô kiếm cuối ngay trước ngày tang. Họ giữ được đơn hàng, còn một hộ từng mất ruộng trong trận đánh mang mảnh bao có dấu lò tới nhận mặt. Người kế nghiệp cất nó cạnh sổ tiền ứng.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Tiếng búa bên vách","t":"Người phụ lò nhóm lửa lại sau khi chôn ngươi. Họ mài lưỡi búa theo vết cũ và treo tờ ghi giá để dân biết trước khi mang cuốc. Những người đứng chờ vẫn gọi chỗ sửa ấy bằng tên ngươi.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Tàn than trong túi áo","t":"Khi ngươi qua đời, gia đình giũ áo ra còn nắm bụi than. Người từng đứng cạnh bễ đến trả chiếc kìm ngươi cho mượn. Họ dùng nó gắp một hòn than để nhóm bếp cho bữa tang."}]},"san":{"len":["Người chợ đã mua mẻ săn do ngươi mang về. Một thợ quen cho biết mùa nào nên để thú non ở lại trong rừng.","Khách thuê ngươi dẫn một chuyến sâu vào rừng. Họ đợi ngươi xem dấu trên đất rồi mới dám bước qua chỗ khuất.","Các thợ săn trao ngươi quyền chọn đường. Trước khi đi, một người hỏi ai sẽ quay về nếu cả nhóm gặp mưa lớn.","Người gác làng đến tìm ngươi vì thú đã xuống sát ruộng. Họ muốn biết đường nào cần đóng để dân khỏi đi nhầm.","Danh thần tiễn đi qua nhiều bản. Người trẻ tới hỏi ngươi có biết lúc nào nên hạ cung để người sau còn vào rừng."],"ket":[{"id":"A","ten":"Lối rừng còn dấu gậy","t":"Sau khi ngươi mất, phường săn giữ một lối qua rừng cho người đi hái củi. Họ cắm dấu ở bãi thú non và thay nhau dẫn khách lúc trời mờ. Gia đình từng được ngươi đưa ra đặt quả khô bên mộ.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Giá lông trên cửa kho","t":"Người mua xếp hàng khi kho mở sau lễ tang. Một thợ từng mất công đem sổ tới hỏi vì sao phần lông nhà họ bị giữ. Các dấu trên sổ vẫn dẫn về giá ngươi từng đặt cho cả phường.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Cây cung gửi người đi trước","t":"Người từng theo ngươi một mùa nhận cây cung sau ngày chôn cất. Họ hạ nó xuống mỗi khi dẫn khách qua đường trơn, làm đúng lời ngươi từng dặn phải nhìn người trước khi nhìn dấu thú.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Bữa thịt dưới mái thấp","t":"Ngươi qua đời, người nhà chỉ còn vài dây phơi và một tấm da chưa bán. Bạn săn mang thịt đến giúp lo tang. Trong bữa, họ nhớ ngươi từng chia phần trước cho người đi xa nhất."}]},"sat":{"len":["Người coi việc đặt thẻ đồng lên bàn. Trước khi lấy, ngươi được đọc tên người thuê và lý do họ ghi trên giấy.","Thẻ bạc đem tới những đơn có nhiều tiền hơn. Một người đưa tin xin ngươi kiểm lại tên trước khi nhận việc.","Người giữ cửa nhận ra thẻ vàng và để ngươi vào bàn xét đơn. Trên bàn có một tờ đã bị trả lại vì thiếu chứng.","Kẻ giao thẻ huyết xin ngươi giữ kín cả tên người thuê. Một người mới đến muốn biết có quyền từ chối hay không.","Khi nhận chỗ lâu chủ, ngươi tìm thấy các đơn còn mở. Có người xin trả thẻ và hỏi bao giờ được rời khỏi cửa."],"ket":[{"id":"A","ten":"Hòm đơn đã trả","t":"Khi ngươi mất, người giữ hòm tìm thấy những đơn ngươi từng trả lại vì tên bị ghi sai. Họ gửi bản cho gia đình người thoát nạn, rồi thôi nhận việc dưới dấu của ngươi. Một người mới tự đặt thẻ xuống trước cửa.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Thẻ để lại trên án","t":"Ngươi qua đời, người tranh ghế tới lấy hòm đơn trước khi áo tang được cắt. Một người từng mất cha đem tới nửa tờ thuê có dấu của ngươi. Người mới cầm quyền nhận cả tờ ấy lẫn việc phải trả lời.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Người trả thẻ bạc","t":"Sau ngày chôn ngươi, một người từng đưa tin mang thẻ bạc bỏ vào hòm chung. Họ nhớ có lần ngươi trả một đơn vì chưa được nghe phía còn lại. Từ đó họ hỏi tên người thuê trước khi nhận thư.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Bậc cửa không tên","t":"Ngươi mất ở chỗ trọ, tên thật không ghi trên thẻ. Chủ trọ đem chôn ngươi và gửi lại tiền phòng còn dư cho người quen. Người ấy chỉ nhớ ngươi từng ngồi ăn chậm để chờ họ về."}]},"tho":{"len":["Người coi xưởng giao một món cho ngươi làm từ đầu đến cuối. Khi khách đến, ngươi tự chỉ chỗ đã chỉnh lại.","Thợ mới bắt đầu mang đồ tới nhờ ngươi xem trước khi giao. Ngươi dành một góc bàn cho những món chưa qua lần thử.","Ngươi nhận xưởng và sổ tiền công. Đúng lúc khách giục lấy hàng, thợ phụ tới hỏi có thể về chăm con một hôm không.","Mẫu của ngươi có người từ xa tới xem. Ngươi đặt cả món còn vết lỗi ra cạnh món tốt và nói chỗ phải sửa.","Những xưởng khác gửi thợ tới học một mùa. Ngươi cho họ tự làm mẫu và giữ riêng phần công của người đã giúp."],"ket":[{"id":"A","ten":"Bàn nghề đủ chỗ","t":"Sau khi ngươi mất, học trò giữ một bàn trống cho người mới. Bên cạnh mẫu tốt còn có những món ngươi từng bảo đừng bán khi chưa sửa. Một khách cũ mang chiếc hộp đã dùng nhiều năm tới, xin đặt xuống lúc đưa tang.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Tên thợ bị xóa khỏi nhãn","t":"Xưởng vẫn bán được hàng sau ngày ngươi mất. Những người làm thuê đòi chép lại tên mình vào sổ, vì trên món hàng chỉ có dấu chủ xưởng. Một người mang mẫu từng bị lấy công tới làm chứng.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Hộp gỗ theo mùa","t":"Người từng nhờ ngươi chỉnh cái hộp giữ nó qua nhiều mùa ẩm. Ngày nghe ngươi mất, họ đem về xưởng để thợ mới đo lại bản lề. Thợ dùng vết mòn cũ chỉ ra chỗ được sửa vừa tay.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Mảnh mẫu trong giỏ","t":"Ngươi không để lại xưởng, chỉ có giỏ đồ và một vài mảnh mẫu. Người từng làm chung xin giữ một mảnh để chỉ cho trẻ cách thử đồ trước khi giao. Gia đình dùng chiếc giỏ cũ đựng hương."}]},"thuong":{"ket":[{"id":"A","ten":"Phiếu gửi còn được tin","t":"Ngày đưa tang, một người từng được ngươi trả đủ tiền giữa lúc kho cạn mang phiếu tới. Người kế quầy mở hòm trước họ và tiếp tục giữ lệ cũ. Từ đó khách đi xa còn biết có chỗ gửi hàng, kể cả khi người ký trên phiếu đã qua đời.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Cửa kho bán theo nợ","t":"Con cháu giữ được các kho sau khi ngươi mất. Họ cũng nhận lại sổ những món nợ ngươi từng dùng để buộc người bán sang hàng. Một gia đình tới thắp hương, rồi đứng ngoài sân đòi xem bản mua có ghi đủ giá hay không.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Biển hiệu sang tay","t":"Người phụ quầy mua lại cửa hiệu từ gia đình sau ngày tang. Họ giữ chỗ đặt cân và thay tấm biển đã cong. Một khách quen vẫn hỏi mua đúng loại hàng ngươi từng để riêng ở ngăn dưới.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Đòn gánh ngoài hiên","t":"Ngươi chết khi trong nhà vẫn còn một gánh chưa bán hết. Người cùng chợ mang tiền sang mua số hàng cuối để gia đình lo tang. Đòn gánh kê bên hiên, ngày mưa còn in một đường nước trên vách."}]},"tieu":{"len":["Người mua củi nhận ra bó ngươi buộc. Từ nay ngươi tự chọn cây khô để đốn và tự mang củi ra chợ bán.","Xưởng đặt ngươi đốn những cây lớn. Thợ già đứng lại xem ngươi hạ cây mà không làm gãy bụi non bên cạnh.","Người mua gỗ hỏi giá cả chuyến qua ngươi. Những người kéo gỗ muốn biết họ sẽ được trả trước khi xe rời bãi hay sau.","Ngươi nhận chìa xưởng. Mỗi chiều ngươi phải xem số gỗ nhập và phần công còn thiếu của những người chưa về.","Người coi rừng đem bản ranh tới cho ngươi. Từ nay việc giữ cây quanh nguồn nước cũng thuộc phần ngươi phải lo."],"ket":[{"id":"A","ten":"Dấu vạch giữ nguồn nước","t":"Sau khi ngươi mất, người trong xưởng vẫn chừa một dải cây quanh nguồn nước. Họ ghi vào sổ cả gỗ đã đốn lẫn chỗ phải để cây mọc lại. Mấy người gánh củi chậm bước qua mộ ngươi rồi ra bãi nhận công.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Ranh rừng qua tay người mua","t":"Ngươi để lại nhiều giấy quyền đốn gỗ. Khi tang chưa xong, người mua mới đã cắm lại mốc, chặn lối những hộ từng được vào nhặt củi. Một tiều phu giữ bản mốc cũ để đi hỏi quyền lấy củi cho cả xóm.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Cây ngã đúng lối kéo","t":"Thợ trong xưởng chôn ngươi ở nơi nhìn sang bãi gỗ. Người từng đi với ngươi giữ một cây nêm cũ, vẫn dùng nó chỉ cho người học cách giữ khoảng cách lúc hạ cây. Nhà ngươi nhận phần công cuối đủ lo bữa đưa tang.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Bó củi dưới mái","t":"Ngươi mất mà chỉ còn chiếc rìu mẻ và mấy bó củi khô. Hàng xóm lấy một bó nhóm bếp nấu cơm đưa tang, số còn lại để gia đình dùng. Họ vẫn nhớ ngươi thường gánh thêm một bó cho bà cụ sống một mình."}]},"tieu_su":{"len":["Người giữ đoàn giao ngươi đứng cạnh xe hàng thay vì chỉ chạy trước. Chủ hàng muốn biết sẽ nhận lại món ở đâu.","Ngươi được dẫn một chuyến và phải điểm đủ người lúc qua đèo. Một tiêu đồng đang chờ ngươi cho nghỉ thay giày.","Từ nay ngươi thay người đứng đầu khi một đoàn về muộn. Các nhà gửi hàng đem giấy tới để đối phần còn thiếu.","Cả tiêu cục đợi ngươi chia đường cho những chuyến tới. Có người muốn đổi chuyến để kịp đưa người nhà đi chữa.","Lá cờ tiêu cục được giao cho ngươi cùng những khoản đền còn treo. Một người từng mất hàng đứng chờ ngoài sân."],"ket":[{"id":"A","ten":"Giấy giao tới tận nhà","t":"Sau ngày tang, tiêu cục vẫn cho người nhận cùng kiểm niêm trước lúc ký. Một người từng được đền hàng mang giấy đến thắp hương, rồi giao chuyến mới cho học trò ngươi. Lá cờ cũ còn đi qua những bến quen.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Cờ treo trên sổ thiếu","t":"Tiêu cục nhận cờ sau khi ngươi mất, nhưng một người nhà tiêu đồng đòi phần công chưa trả. Họ lật đúng trang chuyển chuyến năm nọ. Người cầm cờ nay phải đọc khoản thiếu trước những người còn đi đường.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Người đợi đủ xe","t":"Đoàn từng theo ngươi dừng cùng một lúc ở đầu dốc để thắp hương. Họ giữ tờ ghi chỗ có thể đợi xe tụt lại, rồi dạy người mới cách kiểm niêm khi qua chân đèo.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Chiếc dây buộc rương","t":"Khi ngươi mất, đồng nghiệp trả gia đình chiếc dây buộc rương ngươi vẫn mang theo. Nó đã sờn ở chỗ thường xiết nút. Họ dùng tiền của chuyến cuối còn lại để thuê xe đưa tang về quê."}]},"tram":{"len":["Ngựa giao vào tay ngươi cùng một túi thư còn niêm. Người coi trạm dặn lúc ngựa mệt phải báo ngay cho nơi nhận.","Ngươi được giao trực đường thư của quân. Người phát lệnh đặt túi lên bàn và đợi ngươi đọc giờ phải tới.","Chìa chuồng về tay ngươi. Lần đầu đổi phiên, ngươi phải xếp đủ ngựa nghỉ trước khi người đưa thư từ xa tới.","Các trạm đem sổ tới để ngươi sửa giờ giao. Một phu trạm xin chừa ngày nghỉ cho con ngựa đã chạy nhiều hôm.","Ngươi coi cả đường thư. Trong bản lịch mới, có chỗ ghi đường vòng và người cần báo nếu một cửa đèo bị tuyết bít."],"ket":[{"id":"A","ten":"Giờ giao ghi ngoài cửa","t":"Ngày ngươi mất, người qua trạm vẫn có thể xem giờ nhận thư ở cửa. Phu mới giữ một đường vòng đã thử và hai máng nước luôn đầy. Một gia đình đưa tang ngươi vì từng nhận được thư trước ngày phải dời.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Túi thư đến chậm","t":"Người kế trạm nhận sổ có những canh giờ bị bán. Sau lễ tang, một người cầm thư đến muộn yêu cầu ghi ngày thật vào biên bản. Họ muốn biết ai từng trả để túi thư nằm lại trong chuồng.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Máng nước bên đường","t":"Người giữ trạm treo dây cương của ngươi cạnh máng. Sau khi chôn ngươi, họ tiếp tục đánh dấu con nào chưa đủ sức chạy. Một người đưa thư lần đầu ghé trạm nghe họ đọc tên ngươi khi đổi ngựa.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Bậc chuồng đã mòn","t":"Ngươi mất khi còn giữ ngựa cho người khác. Phu trạm cũ tới trả chiếc túi ngươi từng khâu và giúp gia đình dọn rơm. Vết bước chân trên bậc chuồng chưa mất sau nhiều trận mưa."}]},"trom":{"len":["Người coi nhóm giao ngươi trông phần chia sau mỗi vụ trộm vặt. Một đứa mới hỏi có được trả lại món lấy nhầm.","Ngươi đã nổi tiếng vào được những nhà khóa cửa. Người đưa việc tới lần này cầm giấy ghi đồ của nhà đang mắc nợ.","Người trong thành gọi ngươi là đạo vương. Có người đến xin ngươi trả cái ống tiền dành cho một đứa đang bệnh.","Tin về ngươi đi qua nhiều trấn. Nhóm muốn theo phải nói trước họ có chấp nhận để nhà nghèo ra ngoài danh sách.","Người cầm sổ bang đưa ngươi quyền chia việc. Dưới mép bàn còn một danh sách những món chủ cũ đã đến đòi."],"ket":[{"id":"A","ten":"Đồ trả lại trước cửa","t":"Ngày ngươi mất, bang tìm thấy trong hòm nhiều món đã ghi sẵn nơi trả. Họ đem từng món về đúng cửa. Một bà nhận lại chiếc lược rồi lấy phần tiền hàng hôm ấy mua hương, dù vẫn không biết tên thật của ngươi.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Sổ chia còn tên nhà nghèo","t":"Bang giữ được người sau tang lễ, nhưng sổ chia cho thấy cả tiền thuốc từng bị lấy. Một nhà đem túi cũ đến hỏi. Người kế bang phải nghe họ đọc ra từng khoản ngay ở chỗ ngươi từng ngồi.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Một phiếu trả trước tối","t":"Người từng cùng ngươi làm việc ở thành đốt những giấy gọi chuyến sau khi chôn ngươi. Họ giữ lại phiếu của một món đã trả. Trên đó còn lời nhờ người nhận lấy đồ trước lúc chợ đóng.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Bàn tay rời túi áo","t":"Ngươi mất khi tài sản chỉ còn một túi vải rỗng. Một bạn chợ đến gấp túi lại, trả chủ sạp chiếc ghế đã mượn cho ngươi nằm. Họ nhớ ngươi từng trả lại tiền khi nghe chủ túi đi tìm."}]},"vo_gia":{"ket":[{"id":"A","ten":"Sân tập còn sáng","t":"Sau tang lễ, những người từng học võ ở sân ngươi thay nhau mở cửa. Một người già đến xin họ hộ tống sang chợ, còn một đứa trẻ ngồi ngoài thềm đợi được tập. Không ai lấy việc ngươi đã khuất làm cớ khóa sân.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Bảng danh và giấy đòi nợ","t":"Ngày ngươi mất, người trong giang hồ đem tới nhiều bảng tên. Chủ quán từng phải trả tiền mới được yên lại mang giấy đòi phần đã nộp. Người giữ võ quán phải đọc giấy ấy trước khi nhận chiếc ghế của ngươi.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Đường qua võ quán cũ","t":"Mấy người từng được ngươi hộ tống ghé đứng bên mộ. Một người mang gậy tới sân tập, tìm người mới dẫn mình qua dốc. Họ vẫn nhớ ngươi thường đợi khách buộc xong dép mới thúc bước.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Một người nhớ lời hẹn","t":"Ngươi qua đời ở quán nghỉ, thanh binh khí đặt bên vách. Người gác cửa biết tin liền gửi thư về quê cho ngươi. Họ từng chỉ đi cùng ngươi một quãng nhưng vẫn nhớ lời hẹn sẽ giúp báo tin nếu ai gặp nạn."}]},"y":{"ket":[{"id":"A","ten":"Sổ bệnh bên bếp ấm","t":"Ngươi mất, học trò tiếp tục mở hiệu và đọc cả những trang ghi ca từng vượt sức ngươi. Người làng góp củi giữ chỗ chờ, mỗi nhà cử một người trông hộ. Một bệnh nhân cũ đem tới chiếc bát lần đầu họ uống thuốc ở đó.","dk":{"bacNgheTu":4,"nghiep":"thien"}},{"id":"B","ten":"Chìa tủ trong tay người mua","t":"Sau tang lễ, chủ nợ mua lại chìa tủ thuốc. Người nhà của một bệnh nhân mang biên nhận tới, hỏi vì sao họ từng phải đợi dù tủ còn đầy. Học trò mở sổ phí và để họ xem dòng ngươi đã ký.","dk":{"bacNgheTu":4,"nghiep":"ac"}},{"id":"C","ten":"Bàn khám gửi người sau","t":"Khi ngươi nằm xuống, người từng phụ bốc thuốc kê lại bàn khám cho khỏi cập kênh. Họ tiếp tục chữa những bệnh quen, ca nặng thì đưa tới chỗ có người nhận. Một bà cụ giữ toa cũ để nhắc hôm ngươi chịu ngồi nghe bà nói hết.","dk":{"bacNgheTu":2}},{"id":"D","ten":"Túi lá và cối thuốc","t":"Gia đình giữ chiếc cối ngươi dùng từ hồi học bốc thuốc. Sau ngày chôn cất, một người hàng xóm đến xin mượn để giã lá cho con. Họ mang trả trước tối và nhắc ngươi từng thức đêm trông đứa trẻ ấy."}]}},"cc":{"CC01":[{"buoc":0,"id":"ban_bao_che_cu","ten":"Bản bào chế cũ","t":"Ngươi đang lần tìm dấu vết viên đan thì gặp một ông lão bán thuốc rong ngồi nghỉ dưới gốc đa. Nghe ngươi hỏi chuyện dược viện, lão cười khẩy, móc trong tay nải ra một tờ giấy vàng úa, bảo đó là bản chép lại phương thuốc năm xưa. Mép giấy cháy sém, chữ như gà bới. Lão không đòi tiền, chỉ đòi ngươi nghe lão kể chuyện đứa con trai chết vì dịch, năm viện còn chưa có lò đan ấy.","c":[{"id":"nghe_ke","l":"Ngồi xuống nghe lão kể hết","t":"Lão kể rất lâu, có chỗ lặp lại, có chỗ quên tên người. Khi trời ngả chiều, lão gấp tờ giấy đưa cho ngươi xem kỹ: phương thuốc sai mất mấy vị, nhưng nét chữ ở góc dưới đúng là dấu của dược viện. Ngươi biết mình không tìm nhầm chỗ. Lão đứng dậy, phủi đít quần, bảo cứu được ai thì cứu, đừng để ai chết như con lão.","e":{"h":4,"nang":{"duoc":1}}},{"id":"hoi_thang","l":"Hỏi thẳng tờ giấy từ đâu ra","t":"Lão sầm mặt, bảo người trẻ bây giờ chẳng biết nghe ai nói hết câu. Nhưng rồi lão cũng chỉ: tờ giấy nhặt được ở bãi rác sau viện, cùng mấy tấm vải liệm cũ. Ngươi cảm ơn rồi đi, trong lòng vẫn vướng câu chuyện chưa nghe hết.","e":{"nang":{"khao":1}}}]},{"buoc":1,"id":"dua_tre_sot","ten":"Đứa trẻ lên cơn sốt","t":"Đêm thứ mấy trong đoàn cứu dịch ngươi cũng không còn nhớ. Mùi lá ngải khét lẹt lẫn mùi người ốm. Một đứa bé chừng sáu tuổi trong lều cuối cứ lên cơn co giật, mẹ nó ôm chặt mà khóc không ra tiếng. Thầy thuốc trực đêm đã ngủ gục bên nồi thuốc. Thuốc hạ sốt chỉ còn một gói, theo lệ phải để dành cho người lớn khoẻ, những người còn gánh nước, còn đào huyệt cho cả trại.","c":[{"id":"cho_tre","l":"Sắc gói thuốc cuối cho đứa trẻ","t":"Ngươi ngồi quạt lửa tới khi nước thuốc sánh lại. Đứa bé uống được nửa bát, nôn mất một ít, rồi ngủ thiếp đi trong lòng mẹ. Sáng ra trưởng đoàn biết chuyện, mắng ngươi một trận, bắt ngươi gánh thêm nước cả ngày. Lưng ngươi rã rời, nhưng tiếng trẻ con ho trong lều cuối nghe đã đỡ khàn.","e":{"deed":"cuu_nguoi","hp":"-5%"}},{"id":"giu_le","l":"Giữ đúng lệ, đánh thức thầy thuốc","t":"Thầy thuốc dụi mắt, xem mạch đứa bé rồi lắc đầu. Ông lấy khăn ướt đắp trán nó, dặn người mẹ chườm suốt đêm. Gói thuốc vẫn nằm trong rương. Đến gần sáng, cơn sốt tự lui. Không ai biết là may hay là số. Ngươi chỉ biết mình đã không phải chọn thay ai."},{"id":"ngoi_canh","l":"Ngồi canh cùng người mẹ tới sáng","t":"Ngươi thay khăn, thổi lửa, kể vài chuyện vô thưởng vô phạt cho người mẹ đỡ sợ. Trời hửng sáng thì cơn sốt lui. Người mẹ ngủ gục bên con, tay vẫn nắm gấu áo ngươi. Mệt, nhưng trong lòng có chỗ yên.","e":{"nang":{"nhan":1},"tamma":-1}}]},{"buoc":2,"id":"gia_nhan_cong_tu","ten":"Gã gia nhân đưa thư","t":"Trước khi viện chủ định đoạt chuyện viên đan, một gã gia nhân mặc áo lụa tìm tới chỗ ngươi nghỉ. Hắn nói công tử nhà hắn biết ngươi đã khổ công nhiều tháng, nên sẵn lòng đền bù: một túi bạc nặng tay, đủ cho người như ngươi sống mấy năm không phải làm thuê. Đổi lại, ngươi chỉ cần không nhắc gì với viện chủ nữa. Hắn đặt túi bạc lên chiếu, mắt không rời mặt ngươi.","c":[{"id":"day_lai","l":"Đẩy túi bạc trả lại","t":"Gã gia nhân nhún vai, cất túi bạc, bảo công tử sẽ không vui. Hắn đi rồi, ngươi ngồi lại một mình rất lâu. Mười tám tháng qua hiện lên từng mảnh: những cái lều, những tấm chiếu cuốn người, đứa bé lên cơn sốt. Ngươi biết mình không đổi chúng lấy bạc.","e":{"tamma":-2}},{"id":"nhan_bac","l":"Nhận một nửa, coi như tiền công","t":"Ngươi nhận một phần, bảo phần còn lại cứ đem về. Gã gia nhân cười nhạt, như đã quá quen loại người này. Đêm ấy ngươi trằn trọc, nghe tiếng chuột chạy trên mái. Túi bạc nằm cạnh gối, lạnh hơn ngươi tưởng.","e":{"bac":800,"tamma":3}}]},{"buoc":3,"id":"goi_thuoc_bi_am","ten":"Gói thuốc bị ẩm","t":"Mưa dầm suốt mấy hôm, kho thuốc của viện dột một góc. Khi ngươi tới nhận phần Hộ Mạch Tán, người giữ kho mặt tái mét: mấy gói bị nước thấm, bột vón lại như đất sét. Lão quỳ xuống xin ngươi đừng báo viện chủ, nhà lão còn ba đứa nhỏ, mất việc thì cả nhà đói. Phía ngoài, tiếng mưa vẫn rơi lộp độp trên tàu lá chuối.","c":[{"id":"giup_phoi","l":"Giúp lão đem thuốc ra hong bên bếp","t":"Hai người ngồi bên bếp lửa suốt đêm, trở từng gói thuốc. Đến sáng, phần lớn đã khô, mùi hơi khét nhưng vẫn dùng được. Lão giữ kho rót cho ngươi chén rượu nhạt, tay còn run. Không ai nhắc chuyện này với ai nữa.","e":{"h":8,"nang":{"duoc":1}}},{"id":"bao_vien","l":"Báo với viện chủ cho đúng phép","t":"Viện chủ nghe xong, không mắng ai, chỉ bảo sửa mái kho trước khi mưa lớn. Lão giữ kho bị phạt nửa tháng công, nhưng không mất việc. Lúc đi ngang ngươi, lão không nhìn lên. Ngươi không biết mình đã làm đúng hay chỉ làm cho yên lòng mình."}]}],"CC02":[{"buoc":0,"id":"vach_mo","ten":"Vạch đo dưới bụi than","t":"Tại {LOC11}, một thợ già nhìn bản đo vỉa mà ngươi đang hỏi mua. Ông chỉ hai dấu dễ nhầm: một dấu chỉ hốc đá, một dấu ghi chỗ thợ phải quay lại. Cạnh bàn, người rao quặng phát sáng đang gọi khách.","c":[{"id":"hoi","l":"Hỏi cách đọc hai dấu trên bản đo","t":"Ông lấy ngón tay lần theo đường vỉa. Ngươi ghi riêng dấu lui để khỏi đọc nhầm lần sau.","e":{"nang":{"khao":1}}},{"id":"nghe","l":"Nghe lời người bán rồi đi hỏi nguồn","t":"Ngươi hỏi quặng lấy từ đâu. Người bán đổi giọng và chỉ một cửa mỏ không có trên bản đo."}]},{"buoc":1,"id":"do_mo","ten":"Thợ vá đèn bên chợ","t":"Trước lúc gom đồ vào mỏ, ngươi gặp một người sửa đèn ở {LOC11}. Họ đặt cạnh nhau chiếc đèn có quai lỏng và một cây chống bị mục chân, rồi hỏi khách có thường nhìn kỹ đồ trước khi mang vào hầm tối không.","c":[{"id":"xem","l":"Ngồi xem người thợ kiểm đồ","t":"Ngươi nhìn họ thử từng món trên mặt đất, rồi ghi các dấu cần hỏi khi mua đồ của mình.","e":{"h":2,"nang":{"canh":1}}},{"id":"don","l":"Giúp dọn chỗ thử trước cửa hàng","t":"Ngươi dọn thúng khỏi lối, để khách sau có chỗ đặt cây chống và xem dưới ánh sáng."}]},{"buoc":2,"id":"cho_cua","ten":"Cùng chờ ngoài cửa mỏ","t":"Một toán đào lậu đến cửa mỏ ở {LOC11} khi đội thợ chưa vào hầm. Hai bên nhìn vào lối chỉ vừa đủ một người. Một phu gùi thấp giọng xin đừng vây kín cửa, vì nhà anh vẫn có người đang làm gần đó.","c":[{"id":"chua_loi","l":"Yêu cầu cả hai bên chừa lối ra","t":"Ngươi nhắc có người còn gần cửa. Hai nhóm lùi lại, đủ chỗ cho phu gùi bước ra hỏi tin."},{"id":"nghe_phu","l":"Đưa phu gùi ra ngoài để hỏi","t":"Ngươi đi cùng anh tới bờ đá. Anh chỉ nơi các gia đình thường đứng đợi khi đổi ca.","e":{"h":2}}]},{"buoc":3,"id":"ten_chong","ten":"Tên khắc trên thanh chống","t":"Trong lúc thăm dò và chống hầm ở {LOC11}, ngươi thấy một thanh chống cũ khắc tên thợ. Một người trong ca nhận ra tên cha, bảo nhà họ chưa từng biết ông làm ở đoạn nào trước lúc mỏ bỏ.","c":[{"id":"sao","l":"Chép tên và vị trí cho người nhà","t":"Ngươi ghi đoạn hầm cùng nét khắc còn đọc được. Người thợ gói tờ giấy trước khi xuống ca.","e":{"h":2}},{"id":"cho","l":"Đứng chờ họ tự xem nét khắc","t":"Ngươi giữ đèn ở mép lối. Họ nhìn một lúc rồi quay ra, xin chưa kể chuyện này cho ai."}]}],"CC03":[{"buoc":0,"id":"ban_pha","ten":"Trang phả thiếu tên cây","t":"Người giữ gia phả ở {LOC01} đặt trang khuyết cạnh bản dập bia. Tên một vật liệu vẫn còn, nhưng dòng bên dưới mất nét. Một bà từng chăm vườn nói đừng vội mua bản chép ở chợ chỉ vì nó đủ chữ.","c":[{"id":"doi","l":"So hai bản trước mặt bà","t":"Bà đọc chỗ mình từng biết. Ngươi ghi riêng phần còn ngờ, để sau này không chép đoán thành thật.","e":{"nang":{"khao":1}}},{"id":"hoi","l":"Hỏi bà về công việc trong vườn","t":"Bà kể khi nào phải nghỉ tay để đất hồi. Ngươi nghe hết rồi trả bản ngay trước lúc mưa."}]},{"buoc":1,"id":"loi_gieng","ten":"Lối ra giếng qua vườn cũ","t":"Địa chủ đòi phần vườn ở {LOC01}, trong khi dân vẫn đi qua đó ra giếng. Một người gánh nước chỉ hàng rào sắp dời. Bà xin các bên đừng bàn quyền giữ vườn mà quên lối đi của những nhà cuối xóm.","c":[{"id":"ghi_loi","l":"Ghi lời những hộ dùng lối giếng","t":"Ngươi hỏi từng hộ rồi chép cùng một tờ, để họ có thể mang tới buổi bàn về vườn.","e":{"h":3}},{"id":"giu_ganh","l":"Đỡ gánh cho bà qua hàng rào","t":"Ngươi giữ thùng cho khỏi đổ. Bà qua được, rồi tự quay lại chỉ lối cho người tới sau."}]},{"buoc":2,"id":"kenh_bun","ten":"Bữa trưa bên kênh","t":"Trong những ngày dọn kênh nuôi vườn, bùn bám tới khuỷu tay. Một người già ở {LOC01} đem cơm ra cho thợ nhưng chỉ đủ vài bát. Bà hỏi có thể chia phần ngay trước khi đội cuối lên bờ hay không.","c":[{"id":"cho","l":"Đợi đội cuối lên rồi cùng chia","t":"Ngươi đậy nồi để cơm khỏi nguội. Lúc cả đội tới, bà nhìn đủ người rồi mới xới.","e":{"h":2}},{"id":"mua","l":"Góp tiền mua thêm cơm","t":"Ngươi đưa tiền cho người chạy chợ. Người coi kênh chừa riêng phần cho đội chưa lên.","dk":{"bacTu":80},"e":{"bac":-80}}]},{"buoc":3,"id":"hoi_nguon","ten":"Mẫu nào đến từ đâu","t":"Ở chỗ gom đồ cho vườn, người bán đặt nhiều vật giống nhau lên mâm. Một người từng chăm cây nhắc ngươi hỏi nơi lấy từng mẫu và ai giữ phần còn lại. Họ không muốn dân bóc trụi một bờ vì lời đồn.","c":[{"id":"hoi","l":"Hỏi người bán ghi nơi lấy từng mẫu","t":"Người bán viết nơi họ nhớ. Ngươi giữ lại câu nào chưa có chứng để hỏi tiếp lần sau.","e":{"nang":{"khao":1}}},{"id":"bao","l":"Nhắc khách chừa phần đang mọc","t":"Ngươi chỉ bờ đất còn non. Hai người mua đồng ý đợi lời người chăm vườn trước khi tới đó."}]},{"buoc":4,"id":"chia_nuoc","ten":"Vườn qua đợt hạn","t":"Trong những mùa chăm vườn ở {LOC01}, mức nước hạ thấp hơn hòn đá đánh dấu. Người cùng giữ vườn nói mấy hộ bên dưới cũng chỉ còn một máng. Họ xin ngươi cùng xem lúc nào có thể chia phiên tưới.","c":[{"id":"chia","l":"Cùng các hộ kê lại phiên tưới","t":"Ngươi chép giờ từng nhà lấy nước và dành chỗ cho hộ có người bệnh không khiêng nổi gánh.","e":{"h":4}},{"id":"tuoi","l":"Nhận một lượt tưới muộn","t":"Ngươi ở lại tới khi người cuối lấy nước xong, rồi mới kéo gáo để tưới phần mình trông.","e":{"h":5}}]}],"CC04":[{"buoc":0,"id":"so_lich","ten":"Lịch sen và lịch thuế","t":"Ở {LOC09}, người coi sổ mở trang thuế nước có ghi một mùa sen nở. Một bà già nói năm ấy nhà bà đánh cá muộn. Hai cách nhớ không cùng ngày, nhưng dấu nước trên bậc nhà vẫn còn.","c":[{"id":"doi","l":"Cùng bà so lại vạch nước","t":"Ngươi hỏi lúc nào thuyền phải cột cao hơn và ghi cạnh ngày trong sổ, để còn tra tiếp.","e":{"nang":{"giac":1}}},{"id":"nghe","l":"Nghe người coi sổ đọc cả trang","t":"Ngươi nghe luôn phần thu sau mùa sen. Một dòng ghi rõ sổ được sao muộn hơn buổi đo nước."}]},{"buoc":1,"id":"ho_can","ten":"Những hộ cần nước dưới đập","t":"Người coi hồ ở {LOC09} chỉ bờ cạn vì dòng bị chặn. Một hộ dưới đập muốn cứu hồ, nhưng lo nhà mình chịu hết nước tràn lúc đổi dòng. Họ hỏi có ai chịu ghi cả phần lo của họ trước buổi bàn không.","c":[{"id":"ghi","l":"Ghi ý của hộ dưới đập","t":"Ngươi để hộ tự đọc lời mình trước người coi hồ. Họ xin có mặt khi hai bên nói chuyện.","e":{"h":2}},{"id":"bao","l":"Giúp báo tin cho nhà vắng","t":"Ngươi đem lời hẹn xuống bờ dưới, tránh để họ chỉ nghe tin sau khi mọi việc đã bàn xong."}]},{"buoc":2,"id":"coi_sen","ten":"Lượt canh sen lúc tối","t":"Một người coi sen ở {LOC09} phải về trông con ốm. Họ nhờ ngươi ngồi lại một lượt, chỉ xem mực nước và đừng chạm vào những đài đang non. Trong chòi có một ngọn đèn sắp cạn dầu.","c":[{"id":"truc","l":"Trông chòi thay họ một lượt","t":"Ngươi ngồi đến lúc họ trở về, ghi mực nước lên bảng. Đài sen vẫn nguyên dưới sương.","e":{"h":6,"nang":{"nhan":1}}},{"id":"goi","l":"Tìm người đổi phiên đã quen hồ","t":"Ngươi gọi một người biết lối bờ. Họ mang theo dầu và tự nhận lượt trước khi trời tối."}]}],"CC05":[{"buoc":0,"id":"gang_cu","ten":"Găng cũ trên bàn rèn","t":"Tại {LOC11}, một người bán dụng cụ bày găng còn ám khói cạnh mấy món dùng gần lửa. Thợ phụ xin ngươi phân biệt món đã chai với món chỉ bị bẩn. Ngươi có thể xem trước, còn việc mua vẫn phải hỏi người giữ quầy.","c":[{"id":"xem","l":"Xem người thợ thử độ mềm","t":"Ngươi bóp thử phần găng cũ vừa được đưa ra. Thợ phụ chỉ chỗ nứt bị giấu dưới muội.","e":{"nang":{"khao":1}}},{"id":"hoi","l":"Hỏi chỗ sửa đồ đã dùng lâu","t":"Người bán chỉ bàn vá ở cuối xưởng. Ngươi ghi giờ người thợ có mặt rồi rời quầy."}]},{"buoc":1,"id":"trang_chay","ten":"Sổ tôi lửa có trang cháy","t":"Mảnh lò và sổ cũ ở {LOC11} mang cùng dấu búa, nhưng trang ghi về hạt lửa bị cháy mất góc. Thợ rèn già muốn nghe ngươi đọc đúng phần còn lại, để lời đồn ngoài chợ khỏi điền vào chỗ thiếu.","c":[{"id":"doc","l":"Đọc phần còn thấy cho thợ nghe","t":"Ngươi đọc chậm, dừng ở nét không chắc. Ông chép thêm ngày bản sổ từng được chuyển kho.","e":{"h":2}},{"id":"sao","l":"Xin vẽ lại dấu búa","t":"Ông đưa giấy để ngươi vẽ dấu. Bản chính vẫn đặt trên bàn, chưa ai nhận đã tìm được tàn lò."}]},{"buoc":2,"id":"ban_do","ten":"Người bị mất bản đồ","t":"Kẻ rao bán bản đồ tàn lò đã bỏ đi khỏi quầy. Một thợ phường rèn ở {LOC11} còn nhớ buổi bản ấy bị lấy, nhưng sợ có người gọi mình là đồng lõa. Ông xin giữ một bản lời khai nếu phải ra mặt.","c":[{"id":"ghi","l":"Chép lời ông thành hai bản","t":"Ngươi trao ông một bản và hỏi khi nào được dùng bản kia. Ông nhận giấy rồi hẹn tới phường.","e":{"h":3}},{"id":"giu","l":"Chỉ hỏi điều ông chịu nói công khai","t":"Ông cho biết buổi mất bản, nhưng giữ lại tên người đi cùng. Ngươi ghi đúng phần đã nghe."}]},{"buoc":3,"id":"ghe_lo","ten":"Chỗ ngồi của thợ coi lửa","t":"Trong lúc chuẩn bị đồ hộ tâm và giữ lửa, người học việc ở {LOC11} chỉ cái ghế sứt cạnh lò. Thợ coi lửa phải ngồi đó tới cuối ca, có hôm không kịp ăn. Họ hỏi ai sẽ mang cơm khi ca kéo dài.","c":[{"id":"mang","l":"Mang cơm cho người coi lửa","t":"Ngươi đặt bát ở bàn thấp ngoài lò để họ ăn lúc đổi người, tránh vướng tay khi đang làm.","e":{"h":2}},{"id":"doi","l":"Giúp sửa chân ghế đang lung lay","t":"Ngươi chèn lại chân ghế rồi để người coi lửa tự thử. Họ bảo sẽ xin nghỉ nếu ca còn quá dài."}]}],"CC06":[{"buoc":0,"id":"mat_sau","ten":"Dòng cho phép rút khế","t":"Một người ở {LOC08} đem khế cũ ra đối. Mặt trước ghi phần huyết mạch được chia, mặt sau ghi khi nào linh thú có thể rời đi. Người giữ chuồng nói bản bán ngoài chợ thường không sao dòng sau.","c":[{"id":"doc","l":"Nhờ đọc cả hai mặt trước khi bàn","t":"Ngươi nghe hết phần rút khế và chép câu chưa rõ. Người giữ chuồng chỉ người có thể hỏi tiếp.","e":{"nang":{"khao":1}}},{"id":"hoi","l":"Hỏi người trông thú về dấu từ chối","t":"Người trông thú nói lúc con vật lùi khỏi cửa thì họ dừng. Ngươi giữ lời ấy khi tới chuồng."}]},{"buoc":1,"id":"bat_nuoc","ten":"Con thú quay mặt vào vách","t":"Con linh thú hợp huyết đang bị thương trong chuồng ở {LOC08}. Khi người lạ gọi, nó quay mặt vào vách. Người nuôi nói nó vẫn ăn nếu để bát ở cửa rồi cho nó một khoảng yên.","c":[{"id":"giu","l":"Giúp người nuôi dọn bát và chờ","t":"Ngươi dọn bát cũ rồi lùi khỏi cửa. Con thú tự tới uống, không ai mang giấy khế ra.","e":{"h":2}},{"id":"di","l":"Rời chuồng để nó nghỉ","t":"Ngươi rời chỗ đứng. Người nuôi đóng tấm rèm thưa, vẫn để lối cho con thú nhìn ra ngoài."}]},{"buoc":2,"id":"tho_chep","ten":"Thợ chép nghỉ tay","t":"Trong lúc tìm giấy khế ở {LOC08}, ngươi gặp người thợ chép bị đau cổ tay. Bản mẫu trên bàn đã hoàn thành, nhưng phía ngoài nhiều người thúc. Một học trò muốn tập đọc phần ghi quyền rút.","c":[{"id":"doc","l":"Đọc mẫu cùng người học việc","t":"Ngươi đọc rõ phần bên nào có quyền dừng. Người học tự chép vào sách tập, còn mẫu vẫn nằm trên bàn.","e":{"h":2}},{"id":"bao","l":"Mời người ngoài quay lại sau","t":"Ngươi nói thợ cần nghỉ và xin họ hẹn giờ khác. Nhờ vậy người học có một buổi đọc lại."}]}],"CC07":[{"buoc":0,"id":"loi_nguoi_cho","ten":"Lời người cho căn","t":"Người bệnh tại {LOC07} muốn tự nói chuyện với ngươi. Họ đẩy giấy sang một bên để hỏi điều gì sẽ xảy ra với người nhà mình. Một người coi quán nhắc cứ xem hồ sơ trước khi tin hộp gỗ rao ngoài chợ.","c":[{"id":"nghe","l":"Để người bệnh nói trước","t":"Ngươi nghe họ nói hết rồi mới hỏi chỗ ghi điều đã đồng ý. Họ xin được giữ một bản.","e":{"h":2}},{"id":"hoi","l":"Hỏi người coi quán nơi tra hồ sơ","t":"Người coi chỉ chỗ ghi bệnh án và dặn đừng trả tiền cho món hàng chưa rõ nguồn."}]},{"buoc":1,"id":"bua_yen","ten":"Bữa ăn trước ngày chọn","t":"Người có căn nằm yếu, còn người nhà chưa thống nhất. Người coi y quán mang thêm giấy rao một nguồn khác. Người bệnh hỏi có thể cất giấy đi để mọi người được ăn một bữa yên trước khi bàn không.","c":[{"id":"bep","l":"Dọn bữa cho người bệnh và người nhà","t":"Ngươi đặt bát trong tầm tay rồi tránh ra. Họ có thời gian nói riêng mà không phải ký gì.","e":{"h":3}},{"id":"doi","l":"Xin người coi quán để giấy ngoài cửa","t":"Người coi cất giấy đi. Ngươi nhắc người nhà hỏi chính người bệnh trước khi tới bàn."}]},{"buoc":2,"id":"phieu_nhan","ten":"Phiếu ghi người nhận","t":"Trong lúc chuẩn bị vật tư, người phụ việc ở {LOC07} muốn có giấy ghi ai nhận từng món và ai chịu trách nhiệm cấy căn. Một dòng bị bỏ trắng cho người có nghề, dù người bán cứ bảo ngươi đặt tiền trước.","c":[{"id":"tra","l":"Kiểm ai đứng tên chịu trách nhiệm","t":"Ngươi hỏi từng vai đứng tên, ghi riêng phần chưa ai nhận. Chưa có món nào đổi chủ.","e":{"nang":{"khao":1}}},{"id":"giu","l":"Giữ bản kê để hỏi lại người có nghề","t":"Ngươi gập bản kê vào túi và hẹn trở lại khi người có nghề tự xác nhận phần mình."}]}],"CC08":[{"buoc":0,"id":"doi_sao","ten":"Mưa che ngày sao rơi","t":"Người coi thiên tượng ở {LOC05} trải hai bản chép về đêm sao rơi. Một bản ghi mưa lớn, bản kia vẽ bầu trời quang. Người chép trẻ nhờ ngươi xem ngày ghi trên mép, vì có thể họ chỉ khác cách tính ngày.","c":[{"id":"doi","l":"So ngày nhận bản với ngày ngắm sao","t":"Ngươi giúp tách ngày sao rơi khỏi ngày người chép nhận giấy, rồi đánh dấu phần còn ngờ.","e":{"nang":{"khao":1}}},{"id":"nghe","l":"Nghe người chép kể ai trao bản","t":"Ngươi ghi tên vai người giao từng bản để thợ trận có thể tìm nguồn mà đối sau."}]},{"buoc":1,"id":"the_sao","ten":"Hòm trưng ba vệt sáng","t":"Người sưu tầm ở {LOC05} treo hình ba mảnh sao để khách phân biệt. Một đứa học việc định đổi chỗ tên ghi dưới hình vì nhìn màu giống nhau. Nó hỏi ngươi có thấy chữ ở lưng thẻ không.","c":[{"id":"chi","l":"Chỉ chữ dưới lưng thẻ cho học đồ","t":"Ngươi lật thẻ trước mặt nó, giữ nguyên thứ tự để khách sau còn biết hình nào đang xem."},{"id":"hoi","l":"Hỏi vì sao tên thẻ dễ bị nhầm","t":"Ngươi nghe người coi giải thích về ánh đèn, rồi ghi điều cần kiểm trước khi nhận hàng.","e":{"h":2}}]},{"buoc":2,"id":"loi_dan","ten":"Tên người chép trong trận đồ","t":"Khi khảo trận tại {LOC05}, ngươi thấy trang ghi về ký ức phải trao ở cuối tập. Học đồ bên cạnh hỏi nếu phải bỏ một kỹ năng đã học, có nên để lại lời dặn cho người đang dựa vào nó không.","c":[{"id":"viet","l":"Dành thời gian viết lời dặn","t":"Ngươi chép việc cần bàn giao cho người đang trông đợi mình. Trang về trận vẫn nằm nguyên.","e":{"h":4}},{"id":"hoi","l":"Hỏi học đồ từng thấy ai chuẩn bị chưa","t":"Họ kể người trước chỉ kịp gửi một lá thư. Ngươi ghi nơi để thư, phòng khi cần."}]}],"DUOC_NHAN":[{"buoc":0,"id":"nguoi_tro_ve","ten":"Người trở về từ giường thuốc","t":"Ở {LOC07}, một người từng thử thuốc chờ ngươi tại hiên. Họ chỉ vết cũ trên tay, kể có những người không về được. Trên tờ mà y quán phát, chỉ tên những người sống sót được ghi bằng mực đỏ.","c":[{"id":"nghe","l":"Nghe cả phần không ghi trên tờ","t":"Ngươi để họ kể ai đã không về. Khi lời dứt, họ chỉ chỗ gia đình những người ấy thường đợi.","e":{"h":3}},{"id":"hoi","l":"Hỏi họ có giữ bản đã ký không","t":"Họ lấy ra bản gấp nhỏ, chỉ cho ngươi dòng hứa không có trên giấy phát cho khách."}]}],"HUYET_TE":[{"buoc":0,"id":"loi_ngoai_kinh","ten":"Người từng mở mạch xin nói riêng","t":"Một người ở {LOC07} từng dự lễ huyết tế đồng ý cho ngươi xem bản kinh, nhưng xin người đứng lễ ra ngoài trước khi họ kể. Họ muốn ngươi nghe cả tên người đã mất trong lễ, vì tên ấy không có trên giấy.","c":[{"id":"nghe","l":"Đợi họ nói hết rồi mới xem bản kinh","t":"Ngươi chép điều họ cho phép. Khi họ dừng, ngươi cũng dừng, dù phần cuối vẫn chưa rõ.","e":{"h":3}},{"id":"tra","l":"Hỏi ai còn giữ danh sách người có mặt","t":"Họ chỉ nơi người nhà đang lưu giấy. Ngươi rời bàn mà chưa quyết định có dự lễ hay không."}]}],"LINH_CO":[{"buoc":0,"id":"com_nguoi_mang","ten":"Chén cơm của người mang cổ","t":"Người ở {LOC09} cho ngươi hỏi chuyện con cổ trong kinh mạch. Họ đưa một chén cơm đã nguội, nói có những ngày chỉ lo cho con cổ mà quên ăn. Người bán ngoài chợ chỉ kể khúc đầu về cái lợi.","c":[{"id":"hoi","l":"Hỏi việc nuôi cổ mỗi ngày","t":"Họ kể từ ngày nuôi tới những hôm muốn bỏ. Ngươi ghi rõ điều còn phải hỏi người có nghề.","e":{"h":2}},{"id":"moi","l":"Mời họ ăn rồi nghe nốt","t":"Ngươi nhường chén còn ấm của mình. Họ ăn chậm và kể tiếp khi ngoài cửa đã vắng."}]},{"buoc":1,"id":"ong_tre","ten":"Ống tre chưa rõ nguồn","t":"Người rao trứng cổ ở {LOC09} bày nhiều ống tre đã bịt. Học việc bên quầy bảo có ống để từ mùa trước mà chưa ai đối dấu. Nó muốn hỏi chủ nhưng sợ bị đuổi khỏi chỗ làm.","c":[{"id":"hoi","l":"Xin chủ nói rõ gốc từng ống","t":"Ngươi hỏi ngay trước người mua khác. Chủ quầy chỉ được nguồn vài ống, số còn lại phải cất đi.","e":{"nang":{"khao":1}}},{"id":"bao","l":"Dặn học việc giữ lời mình đã thấy","t":"Ngươi khuyên nó chỉ nói điều tận mắt thấy nếu bị hỏi. Nó nhớ ngày đem ống cũ ra sạp."}]}],"QUAN_DINH":[{"buoc":0,"id":"loi_tieu_phu","ten":"Lời chỉ ở ngã rẽ","t":"Gần {LOC04}, một người bán nước nhớ tiều phu từng kể chuyện lão tu sĩ trong hang. Người rao tin ngoài ngõ lại chỉ một lối khác và đòi tiền trước. Bà đưa ngươi ghế, hỏi muốn nghe cả câu chuyện hay chỉ hỏi đường.","c":[{"id":"nghe","l":"Nghe bà kể từ lúc gặp tiều phu","t":"Bà kể cả thời tiết và nơi ông nghỉ chân. Ngươi ghi lại ai đã nghe trực tiếp để còn hỏi.","e":{"h":2}},{"id":"hoi","l":"Xin tên vai người dẫn đường","t":"Bà chỉ người vẫn bán củi vào buổi sớm. Ngươi để dành tiền rồi đi tìm lời xác nhận."}]},{"buoc":1,"id":"bat_nuoc","ten":"Bát nước người bệnh muốn tự nâng","t":"Trong những ngày chăm lão tu sĩ, ngươi thấy tay lão không còn giữ nổi bát nước. Lão vẫn muốn tự nhấp một ngụm trước khi nói chuyện di nguyện. Gần giường còn chiếc ghế đặt cho người tới thăm.","c":[{"id":"ke","l":"Kê bát để lão tự nhấp","t":"Ngươi đặt bát sát mép bàn, đợi lão ra hiệu rồi mới đỡ tay. Lão uống xong mới nói tiếp."},{"id":"cho","l":"Ngồi chờ khi lão muốn nghỉ","t":"Ngươi dời ghế ra hiên rồi quay lại khi lão gọi. Khoảng nghỉ yên hơn mọi lời hứa.","e":{"h":3}}]}],"TAO_HOA":[{"buoc":0,"id":"chu_mo","ten":"Tấm bia mờ ở đường lên","t":"Gần {LOC15}, người giữ bản dập chỉ một dòng đã mòn trên bia. Chữ còn lại nói thần dịch chỉ giúp người đã có linh căn. Một khách khác lại rao mua để giúp người vô căn trong nhà.","c":[{"id":"doc","l":"Đọc dòng còn nguyên cho khách nghe","t":"Ngươi chỉ phần bia còn rõ, nói chỗ nào mình chưa chắc. Người khách hoãn trả giá để đi hỏi thêm.","e":{"nang":{"khao":1}}},{"id":"hoi","l":"Xin bản dập để so với lời rao","t":"Ngươi xem cả chỗ ghép giấy và ghi lại dấu cũ. Người giữ bia cất bản chính lại sau lượt xem."}]},{"buoc":1,"id":"chia_phan","ten":"Người cùng tìm muốn chia phần","t":"Một tu sĩ cũng tìm đến {LOC15}, mang bản đường bị rách ở đoạn cuối. Họ muốn chia phần trước khi ai thấy được thần dịch. Người dẫn đường xin cả hai đừng quyết thay người còn đứng chờ ngoài cửa.","c":[{"id":"ban","l":"Hỏi ai đã hẹn phần với người dẫn","t":"Ngươi nghe từng lời hẹn, ghi rõ phần chưa ai có quyền nhận. Cả nhóm tiếp tục nói mà chưa giao vật.","e":{"h":2}},{"id":"cho","l":"Để người đến sau đọc lại bản đường","t":"Ngươi chờ họ xem xong rồi cất bản của mình. Người dẫn đường nhận ra một đoạn hai bản đã chép khác nhau."}]},{"buoc":2,"id":"the_binh","ten":"Ghi dấu trước khi nhận bình","t":"Trong lúc tìm thần dịch tại {LOC15}, ngươi thấy người coi bàn kê bình muốn đặt chung vật đã rõ nguồn và vật chưa được đối. Một người học việc đem thẻ tới hỏi có cần ghi ngày nhận mẫu không.","c":[{"id":"ke","l":"Giúp ghi riêng các mẫu chưa đối","t":"Ngươi ghi nhãn rồi đọc lại cho người học việc. Họ để riêng các bình ấy, chưa trao món nào cho ai.","e":{"h":2}},{"id":"tra","l":"Hỏi ai tận mắt thấy mẫu được lấy","t":"Ngươi tìm người giao bình hỏi cho rõ. Họ chỉ xác nhận phần mình nhìn thấy, còn nguồn vẫn cần tra."}]}],"TAY_TUY":[{"buoc":0,"id":"trang_thieu","ten":"Bản kinh chép thiếu trang","t":"Một võ sư ở {LOC12} đặt bản kinh ngoài chợ cạnh bản mà ông từng đọc. Bản bán bỏ hết lời nhắc phải nghỉ. Ngoài hiên, có người đang khoe chỉ cần luyện hết một mùa là mọi mạch sẽ mở.","c":[{"id":"doc","l":"Nhờ võ sư chỉ chỗ bị bỏ","t":"Ông đọc lời dặn về lúc dừng. Ngươi sao phần ấy để không nhầm lời rao với bản kinh.","e":{"nang":{"khao":1}}},{"id":"hoi","l":"Hỏi người từng tận mắt xem buổi luyện","t":"Họ chỉ kể việc đã thấy, không nhận biết kết quả cuối. Ngươi ghi cả chỗ họ không dám chắc."}]},{"buoc":1,"id":"san_lanh","ten":"Buổi thở bên sân lạnh","t":"Trong đợt khổ luyện ở {LOC12}, một người tập cùng ngươi ngồi lại bên bậc vì quá mệt. Họ sợ nghỉ một buổi sẽ bị coi là bỏ cuộc. Người coi sân đem nước tới và hỏi ai chịu đổi phiên.","c":[{"id":"doi","l":"Đổi phiên để họ nghỉ","t":"Ngươi báo người coi sân và nhận buổi sau. Người tập ngồi uống nước tới khi tay hết run.","e":{"h":3}},{"id":"ngoi","l":"Ngồi cùng và gọi người xem giúp","t":"Ngươi chờ bên bậc tới khi người coi sân lại gần. Họ tự kể đã mệt từ lúc nào."}]}],"THIEN_LOI":[{"buoc":0,"id":"ao_mua","ten":"Vết cháy trên áo mưa","t":"Dưới chân núi gần {LOC14}, một người sống sót sau giông cho ngươi xem tấm áo cháy. Họ không nhớ mình đã đứng ở đâu khi sét đánh. Người đưa họ về lại nhớ chỗ tìm thấy, nhưng chưa có ai hỏi.","c":[{"id":"hoi","l":"Hỏi người đã đưa họ về","t":"Ngươi nghe lời người cứu rồi ghi riêng chỗ vết cháy và nơi họ tìm thấy người bị nạn.","e":{"h":2}},{"id":"nghe","l":"Để người sống sót kể theo trí nhớ","t":"Ngươi không giục họ nhớ thêm. Họ tự chỉ phần nào là điều mình thấy và phần nào chỉ nghe kể."}]}],"TUC_CAN":[{"buoc":0,"id":"goi_giac","ten":"Gốc cây không giống trong mộng","t":"Ngươi tìm tới nơi từng thấy trong mộng, nhưng gốc cây đã nghiêng và lối cũ mọc kín cỏ. Một người qua đường nhớ hồi trước có hai gốc sát nhau. Họ hỏi ngươi đang tìm nơi chôn vật hay tìm người từng sống ở đây.","c":[{"id":"ve","l":"Vẽ lại nơi thấy trong giấc mộng","t":"Ngươi đánh dấu gốc cây và hướng lối cũ. Người qua đường chỉ thêm chỗ từng có bậc đất.","e":{"nang":{"giac":1}}},{"id":"hoi","l":"Hỏi họ từng thấy ai ở quanh gốc","t":"Họ chỉ nhớ một người thường ngồi ở đó lúc mưa. Ngươi ghi lại lời kể, chưa nhận người ấy là mình."}]}],"XA_LOI":[{"buoc":0,"id":"so_nguoi_o","ten":"Ngày giữ giới bắt đầu từ đâu?","t":"Sư già ở {LOC12} đưa ngươi xem cuốn ghi người xin ở chùa. Có người đã làm việc lâu mà chưa dám ghi tên, vì còn phải về nuôi mẹ. Lão hỏi ngươi muốn nghe lệ giữ giới hay hỏi cách sắp việc trước.","c":[{"id":"hoi","l":"Hỏi cách giữ lời khi vẫn phải về nhà","t":"Lão nói cứ ghi ngày có thể ở thật. Ngươi chừa chỗ cho những lần phải xin về chăm nhà.","e":{"nang":{"nhan":1}}},{"id":"doc","l":"Đọc lệ cùng người đang chờ ghi tên","t":"Ngươi đọc chậm để họ kịp hỏi. Người ấy xin giữ một bản trước khi tự quyết định."}]},{"buoc":1,"id":"bep_chua","ten":"Tiếng mõ trong buổi chia cơm","t":"Qua những mùa giữ giới tại {LOC12}, ngươi quen nghe mõ rồi mang cơm ra sân. Hôm nay còn một người làm chưa về. Người trông bếp định cất nồi vì sắp hết giờ và hỏi có nên để riêng một bát không.","c":[{"id":"de_phan","l":"Giữ phần cơm cho người vắng","t":"Ngươi đậy bát trong bếp. Khi người làm về, họ ăn xong rồi giúp ngươi rửa nồi.","e":{"h":2}},{"id":"di_hoi","l":"Ra sân sau hỏi họ có cần giúp","t":"Ngươi tìm người ấy đang dọn sân và phụ nốt ít việc, để hai người kịp về trước khi bếp đóng.","e":{"h":3}}]}]},"canh":{"quan_phu.heo1":[{"t":"Hai tên nha dịch tới từ lúc gà chưa gáy, lôi ngươi ra sân đình giữa mặt cả làng. Gậy tre quất xuống lưng, tiếng đếm khô khốc vang trong sương sớm. Mấy bà cụ quay mặt đi. Đánh xong, chúng ném lại tờ giấy gia hạn rồi bỏ đi, để ngươi nằm sấp trên nền đất lạnh. Một đứa bé lén mang ra cho ngươi gáo nước."},{"t":"Lão lý trưởng đọc tên ngươi bằng giọng không vui không buồn. Tên nha dịch mập vén tay áo, nhổ nước bọt vào lòng bàn tay. Mỗi hèo rơi xuống, ngươi nghiến răng đếm theo, tới giữa chừng thì không đếm nổi nữa. Khi xong, chủ quán từng cho ngươi chịu đứng ở rìa đám đông, không nói gì, rồi lặng lẽ quay về."},{"t":"Trời đổ mưa phùn lúc quan sai tới. Họ không vào nhà, chỉ đứng ngoài ngõ gọi tên ngươi ba lần. Trên bãi đất trống đầu thôn, ngươi bị đè xuống chiếc ghế dài. Đau nhất không phải lằn roi, mà là ánh mắt người quen. Tối ấy bà hàng xóm đem sang chén thuốc đắp, bảo nợ thì trả dần, đừng bỏ làng mà đi."}],"quan_phu.heo2":[{"t":"Lần này chúng không đọc tờ giấy nữa. Tên đội nha cầm gậy lim chứ không phải gậy tre. Ngươi nghe tiếng xương mình kêu trước khi thấy đau. Lúc tỉnh lại đã nằm trong chái bếp nhà ai đó, chân tay bó nẹp, có người đang thổi bếp. Ngoài cửa, cáo thị dán trên cây gạo đầu làng phấp phới trong gió."},{"t":"Cả làng bị gọi ra xem, như để răn những kẻ khác. Ngươi đã nghĩ mình chịu được, nhưng tới hèo thứ mấy thì không còn nghĩ gì. Người ta khiêng ngươi về trên tấm phản cũ. Đêm ấy sốt cao, mê sảng gọi tên cha mẹ. Ai đó ngồi bên cả đêm, sáng ra chỉ còn lại bát cháo nguội trên đầu giường."},{"t":"Quan sai tới với dây thừng và gông gỗ. Ngươi bị trói vào cột đình suốt một buổi chiều trước khi bị đánh, để người qua lại nhìn cho kỹ. Khi đòn roi dứt, không ai dám lại gần đỡ. Phải tới khi trời tối hẳn, một gã tiều phu mới lẳng lặng cõng ngươi về, không hỏi han một lời."}],"quan_phu.truyNa":[{"t":"Sáng ra, trên vách đình làng đã có tờ cáo thị mới, mực còn chưa khô. Tên ngươi viết to, nét chữ ngay ngắn của thư lại huyện nha. Mấy đứa trẻ đọc vanh vách, rồi bị người lớn quát im. Từ nay quán nước đầu làng không còn ai mời ngươi ngồi."},{"t":"Một tên sai dịch cưỡi lừa đi khắp các ngả đường, dừng ở mỗi cây đa lại dán một tờ giấy. Trên giấy có tên ngươi, có cả mấy chữ tả mặt mũi, vụng mà giống. Người qua đường liếc ngươi một cái rồi kéo khăn che mặt bước nhanh."},{"t":"Lão mõ làng đi rao từ đầu thôn tới cuối thôn: kẻ nào quỵt nợ không trả, kẻ đó bị quan phủ truy tìm, ai chứa chấp cũng mang tội. Ngươi đứng sau rặng tre nghe hết. Tiếng mõ xa dần, để lại sự im lặng nặng hơn cả đòn roi."}],"quan_phu.lamCong":[{"t":"Họ tới lúc nửa đêm, xích chân ngươi vào một đoàn người rách rưới. Đi bộ mấy ngày tới một công trường đá bên sông. Tiếng búa đục suốt từ sáng tới tối, cơm hẩm mỗi ngày hai bữa. Người nằm cạnh ngươi là một lão thợ mộc nợ tiền thuốc cho vợ, đêm nào cũng lẩm bẩm tính ngày về."},{"t":"Quan phủ giao ngươi cho một nhà giàu trên trấn làm công gán nợ. Ngươi gánh nước, bổ củi, xay lúa, ngủ trong chuồng ngựa. Chủ nhà không đánh, chỉ không bao giờ gọi tên ngươi. Mỗi khi trăng tròn, ngươi khắc một vạch lên cột chuồng, và mỗi vạch là một tháng đời người trôi đi."},{"t":"Đoàn phu đắp đê ở hạ nguồn thiếu người, quan phủ đem những kẻ mắc nợ ra bù vào. Ngươi đứng dưới bùn tới thắt lưng, lưng gánh đất, tay bám cọc tre. Có người chết vì sốt rét, có người trốn mà bị bắt lại. Ngươi học cách sống bằng việc không nghĩ về ngày mai."}],"quan_phu.raTu":[{"t":"Ngày được thả, tên cai ném trả ngươi bộ áo cũ, đã chật vì vai rộng ra, và tờ giấy xoá nợ. Bên ngoài cổng, trời rộng tới choáng mắt. Ngươi đứng rất lâu, không biết nên đi hướng nào. Rồi chân tự bước về phía quê nhà, như nước tìm về chỗ trũng."},{"t":"Ra khỏi công trường, ngươi đi ngang chợ, mùi bánh rán làm bụng quặn lại. Mấy năm qua như một giấc ngủ dài và nặng. Người quen gặp lại nhìn ngươi như nhìn người lạ, có kẻ còn tưởng ngươi đã chết. Nợ đã xoá, nhưng trên tay còn vết chai, trên lưng còn dấu xích."},{"t":"Lão thợ mộc được thả trước ngươi một mùa, để lại câu dặn: ra ngoài thì đừng ngoái đầu. Đến lượt ngươi, cánh cổng gỗ mở ra kẽo kẹt. Ngươi không ngoái lại. Con đường đất đỏ chạy dài trước mặt, hai bên lúa đã chín vàng, như thể thế gian vẫn chờ ngươi."}],"truy.thu":[{"t":"{ke} bước ra khỏi cỏ cao và hạ thấp đầu. Bùn trên chân nó đã khô thành vảy. Nó men nửa vòng quanh ngươi rồi nằm phục ngay ở khoảng đất trống duy nhất."},{"t":"Cành khô gãy rắc phía sau. {ke} đã bám theo tới đây, hơi thở phả trắng dưới tán cây. Nó dừng sát bờ đá, nhìn chằm chằm vào ngươi và gầm một tiếng ngắn."},{"t":"Một đàn chim vụt khỏi bụi. {ke} vừa ló ra trên mô đất, lông còn ướt như đã bơi qua suối để theo dấu. Nó bước ngang mỗi khi ngươi đổi hướng."}],"truy.tac":[{"t":"{ke} đẩy một thân cây đã mục ra chắn lối rồi bước khỏi bóng lau. Bùn còn dính trên gấu áo. Hắn nhận ra ngươi và gọi đám đi cùng ra khỏi hai bên đường."},{"t":"{ke} ngồi trên tảng đá, tay giữ túi lương còn mở. Thấy ngươi, hắn buộc miệng túi lại, đứng dậy hỏi món hôm trước định để tới bao giờ mới tính."},{"t":"Ngọn đèn dầu dưới mái nghỉ đã tắt. {ke} từ phía sau cột bước tới, ngón tay còn đen vì vừa bóp bấc. Hắn hỏi lần này ngươi có chịu đứng lại nghe hắn nói không."}],"truy.tu":[{"t":"{ke} thu phi kiếm về tay, đáp trước mặt ngươi. Áo ngoài còn dính bụi đường. Người ấy nhắc đoạn hai bên gặp nhau lần trước và muốn ngươi trả lời ngay tại đây."},{"t":"Ánh bùa vừa tắt trên mặt tảng đá thì {ke} đã hiện ra bên cạnh. Người ấy kẹp lá bùa vào tay áo, nói đã hỏi qua mấy trạm mới tìm được ngươi."},{"t":"{ke} đứng cạnh giếng bỏ, đang rửa bụi khỏi cổ tay. Người ấy thấy ngươi thì đặt gáo lên miệng giếng và đưa tay về chuôi kiếm, chừa đủ chỗ để nghe một lời."}],"truy.ke":[{"t":"{ke} bước ra, gọi ngươi bằng cái tên rất ít người còn nhớ. Trong tay họ có vạt áo giữ từ lần gặp trước. Họ hỏi đến khi nào ngươi chịu nói về việc đã xảy ra."},{"t":"{ke} để một món đồ cũ lên tảng đá giữa hai người. Mép vải còn sờn đúng chỗ ngươi từng nắm. Họ bảo đã mang nó theo suốt nhiều chặng để hỏi cho ra lẽ."},{"t":"{ke} đứng dưới cành cây thấp, đôi giày bết bùn. Họ chỉ hỏi ngươi có nhớ người từng nằm lại hôm ấy không, rồi đặt chiếc túi đã sờn bên chân."}],"truy.quy":[{"t":"Ngọn đèn xanh đi sát mặt đất rồi đứng yên. {ke} từ bên trong ánh ấy hiện ra, áo rũ thẳng dù gió thổi qua. Bên tai ngươi có tiếng cào rất nhỏ."},{"t":"{ke} chờ dưới mái hiên bỏ trống. Nước từ tay áo nhỏ từng giọt, nhưng đất nơi nó đứng vẫn khô. Khi ngươi nhìn lại, nó đã quay mặt theo hướng ngươi định đi."},{"t":"Tiếng kéo dép từ phía sau bỗng im. {ke} hiện trước mặt ngươi, chẳng để lại dấu chân nào trên đất ướt. Nó giơ tay chỉ về phía ngươi vừa rời khỏi."}],"truy.no":[{"t":"{ke} giở tờ cáo thị trước mặt ngươi, chỉ dấu son và dòng nợ quá hạn. Một góc giấy đã ướt vì mưa. Người ấy bảo nếu đã trả thì đưa biên nhận ra xem."},{"t":"{ke} mang theo cuốn sổ bọc vải, mở đúng trang có tên ngươi. Bên cạnh khoản nợ còn ghi ngày họ đi tìm. Người ấy hỏi ngươi định về phủ hay thanh toán tại đây."},{"t":"{ke} trao tận tay ngươi bản chép giấy đòi nợ. Họ giữ bản có dấu dưới tay áo và đợi ngươi đọc hết, rồi mới hỏi nhà nào đã từng nhận tiền thay."}],"truy.cuop":[{"t":"{ke} nhận ra sợi dây buộc trên túi ngươi và gọi đúng món đồ từng bị lấy. Người ấy giữ lại tờ mua đã nhòe, hỏi ngươi còn định để họ đi tìm bao lâu nữa."},{"t":"{ke} tới cùng một người từng thấy vụ cướp. Họ chỉ dấu trên chiếc hòm vẫn còn nhớ rõ, yêu cầu ngươi tự mở trước mặt cả hai để xem đồ đã đi đâu."},{"t":"{ke} đặt chiếc vỏ rỗng của món bị cướp trước mặt ngươi. Người ấy kể đã phải về tay không và muốn nghe ngươi sẽ trả lại gì trước khi họ quay về."}]}};
